	static _implRegistryImportList = null;

	static prePreInit ({implRegistryImportList}) {
		this._implRegistryImportList = implRegistryImportList;
	}

	
	static _template_getImporterToggles () {
		return {
			hiddenImporterIds: {
				name: "Hidden Importers",
				help: `Importers which should not be shown in the Import Wizard UI.`,
				default: {
					"background-features": true,
					"race-and-subrace-features": true,
				},
				type: "multipleChoice",
				choices: this._implRegistryImportList.getImplementations()
					.map(Impl => ({name: Impl.DISPLAY_NAME_TYPE_PLURAL, value: Impl.ID}))
															.sort(({name: nameA}, {name: nameB}) => SortUtil.ascSortLower(nameA, nameB)),
			},
		};
	}

	
		static _getModelBarAttributes (actorType) {
		switch (actorType) {
			case "npc": return ACTOR_MODEL_BAR_ATTRIBUTES__NPC;
			case "character": return ACTOR_MODEL_BAR_ATTRIBUTES__CHARACTER;
			case "vehicle": return ACTOR_MODEL_BAR_ATTRIBUTES__VEHICLE;
			default: throw new Error(`Unhandled actor type "${actorType}"`);
		}
	}

	static api_getModelBarAttributes (actorType) {
		if (!actorType) return [];

		return Object.values(
			TokenDocument.implementation.getTrackedAttributeChoices(
				TokenDocument.implementation.getTrackedAttributes(actorType),
			),
		)
			.flat()
			.map(({value, label}) => ({value, name: label}));
	}

	
	static _template_getEntityOwnership (help) {
		const out = MiscUtil.copyFast(ConfigConsts._TEMPLATE_ENTITY_OWNERSHIP);
		out.values = Util.Fvtt.getOwnershipEnum();
		out.help = help;
		return out;
	}

