class ConfigSettingInfoColor extends ConfigSettingInfoPrimitive {
	get type () { return "color"; }
	set type (val) {  }

	render (
		{
			DRAFT,
			groupKey,
			k,
			backend,
			isDisabled,
			titleDisabled,
			cbIsDefault,
			current,
		},
	) {
		const $iptText = $(`<input type="text" class="w-100 code mr-2 min-w-0 form-control">`)
			.change(() => {
				if (isDisabled) return;

				const val = $iptText.val().trim();
				if (!val && !this.isNullable) {
					const valDefault = this._getValDefault({backend, groupKey, k});
					DRAFT[groupKey][k] = valDefault;
					$iptText.val(valDefault);
				} else {
					DRAFT[groupKey][k] = (this.isNullable && !val) ? null : val;
				}

				doUpdate(DRAFT[groupKey][k]);
			});

		const $iptColor = $(`<input type="color" class="form-control">`)
			.change(() => {
				if (isDisabled) return;

				$iptText.val($iptColor.val()).change();
			});

		const $ele = $$`<div class="ve-flex-v-center">
			${$iptText}
			${$iptColor}
		</div>`;

		const doUpdate = (val) => {
			$iptText.val(val);
			$iptColor.val(val == null ? "#000000" : val);
			cbIsDefault();
		};

		doUpdate(current);

		const fnDisable = () => {
			$iptText.prop("disabled", true).title(titleDisabled);
			$iptColor.prop("disabled", true).title(titleDisabled);
		};

		const fnReset = () => {
			const valDefault = this._getValDefault({backend, groupKey, k});

			$iptText.val(valDefault);
			$iptColor.val(valDefault == null ? "#000000" : valDefault);

			if (game.user.isGM) {
				$iptText.change();
				return;
			}

			DRAFT[groupKey][k] = undefined;
			cbIsDefault();
		};

		const fnHandleUpdate = () => doUpdate(backend.get(groupKey, k));

		return new this.constructor._RenderMeta({
			$ele,
			fnDisable,
			fnReset,
			fnHandleUpdate,
			isLabel: false,
		});
	}

		_isValidValue (value) {
		return typeof value === "string";
	}
}

