class UtilEvents {
	static init () {
		this.bindDocumentHandlers();
	}

	static getElementData_plutHover (ele) {
		const out = {};

		out.isPreload = ele.getAttribute("data-plut-hover-preload") === "true";
		out.preloadUid = ele.getAttribute("data-plut-hover-preload-uid");

		out.isInline = ele.getAttribute("data-plut-hover-inline") === "true";

		out.page = ele.getAttribute("data-plut-hover-page");
		out.source = ele.getAttribute("data-plut-hover-source");
		out.hash = ele.getAttribute("data-plut-hover-hash");
		out.preloadId = ele.getAttribute("data-plut-hover-preload-id");
		out.hashPreEncoded = !!ele.getAttribute("data-plut-hover-hash-pre-encoded");
		out.pageHover = ele.getAttribute("data-plut-hover-page-hover") || out.page;
		out.sourceHover = ele.getAttribute("data-plut-hover-source-hover") || out.source;
		out.hashHover = ele.getAttribute("data-plut-hover-hash-hover");
		out.hashPreEncodedHover = !!ele.getAttribute("data-plut-hover-hash-pre-encoded-hover");
		out.subhashesHover = ele.getAttribute("data-plut-hover-subhashes-hover");
		out.isFauxPage = ele.getAttribute("data-plut-hover-is-faux-page");
		out.isAllowRedirect = ele.getAttribute("data-plut-hover-is-allow-redirect") === "true";

		out.isDelay = ele.getAttribute("data-plut-rich-link") === "true";

		if (out.isPreload) {
			if (out.preloadId != null) {
				const preloadOptions = ele.getAttribute("data-plut-hover-preload-options");
				if (preloadOptions) out.preloadOptions = JSON.parse(preloadOptions);
			}
		}

		if (out.isInline) {
			const inlineEntry = ele.getAttribute("data-plut-hover-inline-entry");
			const inlineOptions = ele.getAttribute("data-plut-hover-inline-options");

			if (inlineEntry) out.inlineEntry = JSON.parse(inlineEntry);
			if (inlineOptions) out.inlineOptions = JSON.parse(inlineOptions);
		}

		return out;
	}

	static bindDocumentHandlers ({element = document.body} = {}) {
		$(element)
			.on(`click`, `[data-packed-dice]`, function (evt) {
				const $this = $(this);
												if (!$this.attr("onclick")) Renderer.dice.pRollerClickUseData(evt, this).then(null);
			})

									.on(`mouseover`, `[data-plut-hover]`, function (evt) {
				const hoverElementMeta = UtilEvents.getElementData_plutHover(evt.currentTarget);

				let {
					hash,
					hashHover,
				} = hoverElementMeta;

				const {
					isPreload,
					preloadUid,

					isInline,

					page,
					source,
					sourceHover,
					preloadId,
					hashPreEncoded,
					pageHover,
					hashPreEncodedHover,
					subhashesHover,
					isFauxPage,
					isAllowRedirect,

					isDelay,

					preloadOptions,

					inlineEntry,
					inlineOptions,
				} = hoverElementMeta;

				if (isPreload) {
					if (preloadId == null) return;
					Renderer.hover.handlePredefinedMouseOver(evt, this, preloadId, preloadOptions);
					return;
				}

				if (isInline) {
					Renderer.hover.handleInlineMouseOver(
						evt,
						this,
						inlineEntry,
						inlineOptions,
					);
					return;
				}

				if (!pageHover || !sourceHover || !hash) return;

				if (!hashPreEncoded) hash = UrlUtil.encodeForHash(hash);
				if (hashHover && !hashPreEncodedHover) hashHover = UrlUtil.encodeForHash(hashHover);
				if (!hashHover) hashHover = hash;

				if (subhashesHover) {
					const parsed = JSON.parse(subhashesHover);
					hashHover += Renderer.utils.getLinkSubhashString(parsed);
				}

				const hoverMeta = {
					isSpecifiedLinkData: true,

					page: pageHover,
					source: sourceHover,
					hash: hashHover,
					preloadId: preloadId,
										isDelay: isDelay,
					isFauxPage: !!isFauxPage,
					isAllowRedirect: !!isAllowRedirect,
				};
				Renderer.hover.pHandleLinkMouseOver(evt, this, hoverMeta).then(null);
			})
			.on(`mouseleave`, `[data-plut-hover]`, function (evt) {
				Renderer.hover.handleLinkMouseLeave(evt, this);
			})
			.on(`mousemove`, `[data-plut-hover]`, function (evt) {
				Renderer.hover.handleLinkMouseMove(evt, this);
			})
			
						.on(`dragstart`, `[data-plut-rich-link]`, function (evt) {
				
				const entityType = evt.currentTarget.getAttribute("data-plut-rich-link-entity-type");

				const hoverElementMeta = UtilEvents.getElementData_plutHover(evt.currentTarget);

				let {hash} = hoverElementMeta;
				const {
					page,
					source,
					hashPreEncoded,
					subhashesHover,
					isAllowRedirect,
				} = hoverElementMeta;

				if (!page || !source || !hash || !entityType) return;

				if (!hashPreEncoded) hash = UrlUtil.encodeForHash(hash);

				if (subhashesHover) {
					const parsed = JSON.parse(subhashesHover);
					hash += Renderer.utils.getLinkSubhashString(parsed);
				}

				evt.stopPropagation();
				evt.originalEvent.dataTransfer.setData(
					"text/plain",
					JSON.stringify({
						type: entityType,
						subType: UtilEvents.EVT_DATA_SUBTYPE__HOVER,
						page,
						source,
						hash,
						isAllowRedirect,
						originalText: evt.currentTarget.getAttribute("data-plut-rich-link-original-text"),
						tagTag: evt.currentTarget.getAttribute("data-plut-rich-link-tag-tag"),
						tagText: evt.currentTarget.getAttribute("data-plut-rich-link-tag-text"),
					}),
				);
			})
					;

		Renderer.events.bindGeneric({element});

		UtilEvents._ADDITIONAL_DOCUMENT_HANDLERS.forEach(({eventType, selector, fnEvent}) => this._doBindHandler({element, eventType, selector, fnEvent}));

		UtilEvents._BOUND_DOCUMENT_ELEMENTS.add(element);
	}

	static registerDocumentHandler ({eventType, selector, fnEvent}) {
		UtilEvents._ADDITIONAL_DOCUMENT_HANDLERS.push({eventType, selector, fnEvent});
		UtilEvents._BOUND_DOCUMENT_ELEMENTS.forEach(element => this._doBindHandler({element, eventType, selector, fnEvent}));
	}

	static _doBindHandler ({element, eventType, selector, fnEvent}) {
		$(element).on(eventType, selector, fnEvent);
	}

	static unbindDocumentHandlers ({element = document.body} = {}) {
				UtilEvents._BOUND_DOCUMENT_ELEMENTS.delete(element);
	}
}
UtilEvents.EVT_DATA_SUBTYPE__HOVER = `${SharedConsts.MODULE_ID_FAKE}.Hover`;
UtilEvents.EVT_DATA_SUBTYPE__IMPORT = `${SharedConsts.MODULE_ID_FAKE}.Import`;

UtilEvents._BOUND_DOCUMENT_ELEMENTS = new Set();
UtilEvents._ADDITIONAL_DOCUMENT_HANDLERS = [];

class ConstsTaskRunner {
	static TASK_EXIT_COMPLETE = Symbol("taskExitComplete");
	static TASK_EXIT_CANCELLED = Symbol("taskExitCancelled");
	static TASK_EXIT_SKIPPED_DUPLICATE = Symbol("taskExitSkippedDuplicate");
	static TASK_EXIT_SKIPPED_OTHER = Symbol("taskExitSkippedOther");
	static TASK_EXIT_COMPLETE_UPDATE_OVERWRITE = Symbol("taskExitCompleteOverwrite");
	static TASK_EXIT_COMPLETE_UPDATE_OVERWRITE_DUPLICATE = Symbol("taskExitCompleteOverwriteDuplicate");
	static TASK_EXIT_FAILED = Symbol("taskExitCompleteFailed");
	static TASK_EXIT_COMPLETE_DATA_ONLY = Symbol("taskExitCompleteDataOnly");
}

class HelpersFolderPath {
		static getFolderPath (fvttEntity, opts) {
		opts = opts || {};
		const {isAddTrailingSlash, root} = opts;

		const stack = this.getFolderPathFolders(fvttEntity, {root});
		if (!stack?.length) return null;
		const out = stack.map(it => it.name).join("/");
		if (out) return isAddTrailingSlash ? `${out}/` : out;
		return null;
	}

	static getFolderPathFolders (fvttEntity, {root = null} = {}) {
		if (!fvttEntity) return [];

		const stack = [];
		if (fvttEntity.folder && root?.id !== fvttEntity.folder.id) {
			stack.push(fvttEntity.folder);
			let parent = fvttEntity.folder?.folder;
			while (parent?.id && root?.id !== parent?.id) {
				stack.push(parent);
				parent = parent.folder;
			}
		}

		return stack.reverse();
	}

	
		static getContainerPath (fvttEntity, {isAddTrailingSeparator = false} = {}) {
		if (!fvttEntity.system?.container) return null;

		const stack = [];
		let doc = fvttEntity;
		while (doc?.system?.container) {
			const containerDoc = doc.collection.get(doc.system.container);

									if (!containerDoc) return null;

			stack.push(containerDoc);
			doc = containerDoc;
		}
		stack.reverse();

		const out = stack.map(it => it.name);
		if (isAddTrailingSeparator) out.push("");
		return out.join(" → ");
	}

			static isInContainer (fvttEntity) {
		return !!fvttEntity.system?.container;
	}
}

class DuplicateMeta {
	constructor ({mode, existing}) {
		this.mode = mode;
		this.existing = existing;

				this.isSkip = mode === ConfigConsts.C_IMPORT_DEDUPE_MODE_SKIP && existing != null;
		this.isOverwrite = mode === ConfigConsts.C_IMPORT_DEDUPE_MODE_OVERWRITE && existing != null;
			}
}

class ImportSummary {
		constructor (
		{
			imported,
			status,
			entity = null,
		},
	) {
		if (!status) throw new Error(`No "status" provided!`);

		this._imported = imported;
		this._status = status;
		this._entity = entity;
	}

	get imported () { return this._imported; }
	get status () { return this._status; }
	get entity () { return this._entity; }

	static cancelled ({entity = null} = {}) { return new this({status: ConstsTaskRunner.TASK_EXIT_CANCELLED, entity}); }
	static failed ({entity = null} = {}) { return new this({status: ConstsTaskRunner.TASK_EXIT_FAILED, entity}); }
	static completedStub ({entity = null} = {}) { return new this({imported: [], status: ConstsTaskRunner.TASK_EXIT_COMPLETE, entity}); }

	getPrimaryDocument () {
		const primaryImportedDocument = this.getPrimaryImportedDocument();
		if (!primaryImportedDocument) return null;
		return primaryImportedDocument.getPrimaryDocument();
	}

	getPrimaryImportedDocument () {
		return this.imported?.[0] || null;
	}

	
		static NOTIFICATION_LEVEL_INFO = "info";
	static NOTIFICATION_LEVEL_WARNING = "warn";
	static NOTIFICATION_LEVEL_ERROR = "error";

		getNotificationMeta () {
		const firstDoc = this.getPrimaryDocument();

		const name = this.imported?.[0]?.name
			|| firstDoc?.name
			|| this._entity?.name
			|| "(Unnamed Entity)";

		if (this.status === ConstsTaskRunner.TASK_EXIT_CANCELLED) return {message: `Import of "${name}" cancelled.`, level: this.constructor.NOTIFICATION_LEVEL_WARNING};
		if (this.status === ConstsTaskRunner.TASK_EXIT_SKIPPED_DUPLICATE) return {message: `Import of "${name}" was skipped (duplicate found).`, level: this.constructor.NOTIFICATION_LEVEL_WARNING};
		if (this.status === ConstsTaskRunner.TASK_EXIT_SKIPPED_OTHER) return {message: `Import of "${name}" was skipped.`, level: this.constructor.NOTIFICATION_LEVEL_WARNING};
		if (this.status === ConstsTaskRunner.TASK_EXIT_FAILED) return {message: `Failed to import "${name}"! ${VeCt.STR_SEE_CONSOLE}`, level: this.constructor.NOTIFICATION_LEVEL_ERROR};

		if (this.imported?.[0]?.actor) {
			return {message: `Imported "${name}" to actor "${this.imported?.[0]?.actor.name}".`, level: this.constructor.NOTIFICATION_LEVEL_INFO};
		}

		const folderPath = HelpersFolderPath.getFolderPath(firstDoc);
		if (folderPath) {
			const folderType = firstDoc?.folder?.type;
			return {message: `Imported "${name}" to ${folderType} folder "${folderPath}".`, level: this.constructor.NOTIFICATION_LEVEL_INFO};
		}

		if (firstDoc?.pack) {
			const pack = game.packs.get(firstDoc.pack);
			return {message: `Imported "${name}" to ${pack.metadata.type} compendium "${pack.metadata.label}".`, level: this.constructor.NOTIFICATION_LEVEL_INFO};
		}

		return {message: `Imported "${name}".`, level: this.constructor.NOTIFICATION_LEVEL_INFO};
	}

	doNotification () {
		const meta = this.getNotificationMeta();
		switch (meta.level) {
			case this.constructor.NOTIFICATION_LEVEL_INFO: return ui.notifications.info(meta.message);
			case this.constructor.NOTIFICATION_LEVEL_WARNING: return ui.notifications.warn(meta.message);
			case this.constructor.NOTIFICATION_LEVEL_ERROR: return ui.notifications.error(meta.message);
			default: throw new Error(`Unhandled level "${meta.level}"!`);
		}
	}

	
	isFailed () { return this.status === ConstsTaskRunner.TASK_EXIT_FAILED; }
}

class ImportedDocument {
		constructor (
		{
			name = null,
			isExisting = false,
			document = null,
			actor = null,
			embeddedDocument = null,
			pack = null,
		},
	) {
		if (document && embeddedDocument) throw new Error(`Only one of "document" and "embeddedDocument" may be specified!`);
		if (actor && pack) throw new Error(`Only one of "actor" and "pack" may be specified!`);

		this.name = name;
		this.isExisting = isExisting;
		this.document = document;
		this.actor = actor;
		this.embeddedDocument = embeddedDocument;
		this.pack = pack;
	}

	getPrimaryDocument () {
		return this.embeddedDocument
			|| this.document;
	}
}

const {HandlebarsApplicationMixin: HandlebarsApplicationMixin$l, ApplicationV2: ApplicationV2$l} = foundry.applications.api;

