class UtilWorldDataSourceSelector {
	static _SETTINGS_KEY = "data-source-selection";

	static async pInit () {
		await game.settings.register(
			SharedConsts.MODULE_ID,
			this._SETTINGS_KEY,
			{
				name: "World Data Source Selection",
				default: {},
				type: Object,
				scope: "world",
				onChange: data => {
									},
			},
		);
	}

	static async pSaveState (saveableState) {
		await game.settings.set(SharedConsts.MODULE_ID, this._SETTINGS_KEY, saveableState);
		ui.notifications.info(`Saved! Note that you (and connected players) may need to reload for any changes to take effect.`);
	}

	static loadState () { return UtilGameSettings.getSafe(SharedConsts.MODULE_ID, this._SETTINGS_KEY); }

	static isSourceSelectionActive () {
		return (!game.user.isGM && Config.get("dataSources", "isPlayerEnableSourceSelection"))
			|| (game.user.isGM && Config.get("dataSources", "isGmEnableSourceSelection"));
	}

	static isFiltered (pipeline) {
		if (!this.isSourceSelectionActive()) return false;

		const savedState = this.loadState();
		if (savedState == null) return false;

		return !savedState.state?.[pipeline.sourceIdentifierWorld];
	}
}

class DataSourceOutputs {
	constructor ({cacheKeys, contents}) {
		this.cacheKeys = cacheKeys || [];
		this.contents = contents || [];
	}
}

class DataSourceBase {
		constructor (opts = {}) {
		this._brewUtil = opts.brewUtil;
		this._isAutoDetectPrereleaseBrew = !!opts.isAutoDetectPrereleaseBrew;
		this._isExistingPrereleaseBrew = !!opts.isExistingPrereleaseBrew;
	}

	get identifier () { throw new Error(`Unimplemented!`); }

		async pGetOutputs ({uploadedFileMetas, customUrls}) { throw new Error("Unimplemented!"); }

	async _pGetBrewUtil (...args) {
		if (this._brewUtil) return this._brewUtil;
		if (!this._isAutoDetectPrereleaseBrew) return null;
		return this._pGetBrewUtilAutodetected(...args);
	}

		async _pGetBrewUtilAutodetected (...args) { throw new Error("Unimplemented!"); }

		async _pGetCompatibleMergedBrewJson ({json, brewUtil}) {
		if (!brewUtil) return json;

		let cpyJson = MiscUtil.copyFast(json);
		BrewDocContentMigrator.mutMakeCompatible(cpyJson);
		cpyJson = await DataUtil.pDoMetaMerge(CryptUtil.uid(), cpyJson, {isSkipMetaMergeCache: true});
		return cpyJson;
	}
}

class DataSourceUrl extends DataSourceBase {
	async _pGetJson ({url, brewUtil}) {
		const json = await DataUtil.loadJSON(url);

		return this._pGetCompatibleMergedBrewJson({
			json: json,
			brewUtil,
		});
	}

	async _pGetBrewUtilAutodetected (url) {
		const json = await DataUtil.loadJSON(url);
		const {isPrerelease, isBrew} = UtilDataSource.getSourceType(json, {isErrorOnMultiple: true});
		if (isPrerelease) return PrereleaseUtil;
		if (isBrew) return BrewUtil2;
		return null;
	}
}

class DataSourceUrlPredefined extends DataSourceUrl {
	constructor ({url, ...rest}) {
		super({...rest});
		this.url = url;
	}

	get identifier () { return this.url; }

	async pGetOutputs ({uploadedFileMetas, customUrls}) {
		let data;
		try {
			const brewUtil = await this._pGetBrewUtil(this.url);
			if (brewUtil && !this._isExistingPrereleaseBrew) await brewUtil.pAddBrewFromUrl(this.url);

			data = await this._pGetJson({url: this.url, brewUtil});
		} catch (e) {
			const msg = `Failed to load URL "${this.url}"!`;
			ui.notifications.error(`${msg} ${VeCt.STR_SEE_CONSOLE}`);
			console.error(msg);
			throw e;
		}
		return new DataSourceOutputs({
			cacheKeys: [this.url],
			contents: [data],
		});
	}
}

class DataSourceUrlCustom extends DataSourceUrl {
	get identifier () { return `VE_SOURCE_CUSTOM_URL`; }

	async pGetOutputs ({uploadedFileMetas, customUrls}) {
		customUrls = customUrls || [];

		let loadedDatas;
		try {
			loadedDatas = await Promise.all(customUrls.map(async url => {
				const brewUtil = await this._pGetBrewUtil(url);
				if (brewUtil && !this._isExistingPrereleaseBrew) await brewUtil.pAddBrewFromUrl(url);

				return this._pGetJson({url, brewUtil});
			}));
		} catch (e) {
			ui.notifications.error(`Failed to load one or more URLs! ${VeCt.STR_SEE_CONSOLE}`);
			throw e;
		}

		return new DataSourceOutputs({
			cacheKeys: customUrls,
			contents: loadedDatas,
		});
	}
}

class DataSourceFile extends DataSourceBase {
	get identifier () { return `VE_SOURCE_CUSTOM_FILE`; }

	async pGetOutputs ({uploadedFileMetas, customUrls}) {
		uploadedFileMetas = uploadedFileMetas || [];

		const allContent = await uploadedFileMetas.pMap(async fileMeta => {
			if (!fileMeta?.contents) return null;

			const brewUtil = await this._pGetBrewUtil(fileMeta.contents);
			if (brewUtil && !this._isExistingPrereleaseBrew) await brewUtil.pAddBrewsFromFiles([{json: fileMeta.contents, name: fileMeta.name}]);

			return this._pGetJson({fileMeta, brewUtil});
		});

		const contentOut = allContent
			.filter(Boolean);

		return new DataSourceOutputs({
									cacheKeys: contentOut.length ? [null] : [],
			contents: contentOut,
		});
	}

	async _pGetJson ({fileMeta, brewUtil}) {
		const json = MiscUtil.copyFast(fileMeta.contents);

		return this._pGetCompatibleMergedBrewJson({
			json: json,
			brewUtil,
		});
	}

	async _pGetBrewUtilAutodetected (json) {
		const {isPrerelease, isBrew} = UtilDataSource.getSourceType(json, {isErrorOnMultiple: true});
		if (isPrerelease) return PrereleaseUtil;
		if (isBrew) return BrewUtil2;
		return null;
	}
}

class DataSourceSpecial extends DataSourceBase {
		get identifier () { return this._cacheKey; }

		get _cacheKey () { throw new Error(`Unimplemented!`); }

		async _pGet () {
		throw new Error("Unimplemented!");
	}

	async pGetOutputs ({uploadedFileMetas, customUrls}) {
		let loadedData;
		try {
			loadedData = await this.constructor._pGetWithCache(this);
		} catch (e) {
			ui.notifications.error(`Failed to load pre-defined source "${this._cacheKey}"! ${VeCt.STR_SEE_CONSOLE}`);
			throw e;
		}

		return new DataSourceOutputs({
			cacheKeys: [this._cacheKey],
			contents: [loadedData],
		});
	}

	async _pGetBrewUtilAutodetected (...args) { throw new Error("Unimplemented!"); }

	
	static _CACHE = {};

	static async _pGetWithCache (source) {
		if (!source._cacheKey) return source._pGet();

		this._CACHE[source._cacheKey] ||= source._pGet();

		return this._CACHE[source._cacheKey];
	}
}

class DataPostLoaderBase {
		static async pMutPostLoad (json) {}
}

class Charactermancer_Race_Util {
	static async pPostLoadPrereleaseBrew (fileData) {
		const out = {race: []};

		if (fileData.race) out.race.push(...Renderer.race.mergeSubraces(fileData.race, {isAddBaseRaces: true}));

		if (fileData.subrace) {
			const baseListSite = MiscUtil.copyFast((await Vetools.pGetRaces({isAddBaseRaces: true})).race);
			baseListSite.forEach(it => PageFilterRaces.mutateForFilters(it));

			const baseListBrew = MiscUtil.copyFast([...fileData.race || []]);
			baseListBrew.forEach(it => PageFilterRaces.mutateForFilters(it));
			const baseList = [...baseListBrew, ...baseListSite];

			const nxtData = Renderer.race.adoptSubraces(baseList, fileData.subrace);
			const mergedNxtData = Renderer.race.mergeSubraces(nxtData);

			out.race.push(...mergedNxtData);
		}

		return out;
	}
}

class Charactermancer_Race_SizeSelect extends BaseComponent {
		static async pGetUserInput ({sizes}) {
		if (!sizes || !sizes.length) return {isFormComplete: true, data: Parser.SZ_MEDIUM};
		const comp = new this({sizes});
		if (comp.isNoChoice()) return comp.pGetFormData();
		return UtilApplications.pGetImportCompApplicationFormData({comp, isAutoResize: true});
	}
	
		constructor (opts) {
		opts = opts || {};
		super();

		this._sizes = opts.sizes || [Parser.SZ_MEDIUM];
	}

	get modalTitle () { return `Choose Size`; }

	render ($wrp) {
		if (this._sizes.length === 1) {
			$wrp.append(`<div>${Parser.sizeAbvToFull(this._sizes[0])}</div>`);
			return;
		}

		ComponentUiUtil.$getSelEnum(
			this,
			"size",
			{
				values: this._sizes,
				isAllowNull: true,
				fnDisplay: Parser.sizeAbvToFull,
			},
		)
			.appendTo($wrp);
	}

	isNoChoice () { return this._sizes.length <= 1; }

	pGetFormData () {
		return {
			isFormComplete: this._state.size != null,
			data: this._sizes.length === 1 ? this._sizes[0] : this._state.size,
		};
	}
}

class DataPostLoaderCommon extends DataPostLoaderBase {
	static async pMutPostLoad (json) {
		await this._pMutPostLoad_raceSubrace({json});
	}

		static async _pMutPostLoad_raceSubrace ({json}) {
		if (!json.race?.length && !json.subrace?.length) return;

		const postLoaded = await Charactermancer_Race_Util.pPostLoadPrereleaseBrew(json);
		Object.assign(json, postLoaded);
		delete json.subrace;
	}
}

class DataPipeline {
		constructor (
		{
			name,
			source,
			filterTypes,
			filterStatus,
			filterMisc,
			abbreviations,
			isDefault = false,
			isWorldSelectable = false,

			dataSource,
			DataPostLoader = null,
		},
	) {
		this.name = name;
		this.source = source;
		this.filterTypes = filterTypes || [DataPipelineConsts.SOURCE_TYP_UNKNOWN];
		this.filterStatus = filterStatus || "ready";
		this.filterMisc = filterMisc || [];
		this.abbreviations = abbreviations;
		this.isDefault = isDefault;
		this.isWorldSelectable = isWorldSelectable;

		this._dataSource = dataSource;
		this._DataPostLoader = DataPostLoader;
	}

	get sourceIdentifier () { return this._dataSource.identifier; }
	get sourceIdentifierWorld () { return this.isDefault ? "5etools" : this.sourceIdentifier; }

	
	isTypeFile () { return this._dataSource instanceof DataSourceFile; }
	isTypeUrl () { return this.isTypeUrlPredefined() || this.isTypeUrlCustom(); }
	isTypeUrlPredefined () { return this._dataSource instanceof DataSourceUrlPredefined; }
	isTypeUrlCustom () { return this._dataSource instanceof DataSourceUrlCustom; }
	isTypeSpecial () { return this._dataSource instanceof DataSourceSpecial; }

	
	async pGetPostProcessedOutputs ({uploadedFileMetas, customUrls}) {
		const meta = await this._dataSource.pGetOutputs({uploadedFileMetas, customUrls});

		meta.contents = await meta.contents
			.pMap(async json => {
				json = {...json};
				await DataPostLoaderCommon.pMutPostLoad(json);
				if (this._DataPostLoader) await this._DataPostLoader.pMutPostLoad(json);
				return json;
			});

		return meta;
	}
}

class DataPipelinesListBase {
	static async pGetPipelines ({isApplyWorldDataSourceFilter = true} = {}) {
		return (await this._pGetPipelines())
			.filter(pipeline => !isApplyWorldDataSourceFilter || !UtilWorldDataSourceSelector.isFiltered(pipeline));
	}

	static get NAME () {
		const propApprox = this.name.replace("DataPipelinesList", "").lowercaseFirst();
		return Parser.getPropDisplayName(propApprox);
	}

	static get ID () {
		return this.name;
	}

	
		static async _pGetPipelines () {
		return [
			...await this._pGetPipelinesOfficialAll(),
			...await this._pGetPipelinesCustomUrl(),
			...await this._pGetPipelinesUploadFile(),
			...await this._pGetPipelinesOfficial(),
			...await this._pGetPipelinesPrerelease(),
			...await this._pGetPipelinesBrew(),
		];
	}

	
		static _CONFIG;

		static async _pGetPipelinesOfficialAll () { return []; }

		static async _pGetPipelinesOfficial () { return []; }

		static async _pGetPipelinesCustomUrl () {
		return [
			new DataPipeline({
				name: "Custom URL",
				filterTypes: [DataPipelineConsts.SOURCE_TYP_CUSTOM],

				dataSource: new DataSourceUrlCustom(
					{
						isAutoDetectPrereleaseBrew: true,
					},
				),
				DataPostLoader: this._CONFIG.ClsDataPostLoaderPrereleaseBrew,
			}),
		];
	}

		static async _pGetPipelinesUploadFile () {
		return [
			new DataPipeline({
				name: "Upload File",
				filterTypes: [DataPipelineConsts.SOURCE_TYP_CUSTOM],

				dataSource: new DataSourceFile(
					{
						isAutoDetectPrereleaseBrew: true,
					},
				),
				DataPostLoader: this._CONFIG.ClsDataPostLoaderPrereleaseBrew,
			}),
		];
	}

		static async _pGetPipelinesPrerelease () {
		if (!this._CONFIG.DIRS_HOMEBREW?.length) return [];

		return this._pGetSourcesPrereleaseBrew({
			brewUtil: PrereleaseUtil,
			localSources: await Vetools.pGetLocalPrereleaseSources(...this._CONFIG.DIRS_HOMEBREW),
			sources: await Vetools.pGetPrereleaseSources(...this._CONFIG.DIRS_HOMEBREW),
						filterTypesLocalPartnered: [DataPipelineConsts.SOURCE_TYP_PRERELEASE, DataPipelineConsts.SOURCE_TYP_PRERELEASE_LOCAL],
			filterTypesLocal: [DataPipelineConsts.SOURCE_TYP_PRERELEASE, DataPipelineConsts.SOURCE_TYP_PRERELEASE_LOCAL],
						filterTypesPartnered: [DataPipelineConsts.SOURCE_TYP_PRERELEASE],
			filterTypes: [DataPipelineConsts.SOURCE_TYP_PRERELEASE],
			ClsDataPostLoader: this._CONFIG.ClsDataPostLoaderPrerelease,
		});
	}

		static async _pGetPipelinesBrew () {
		if (!this._CONFIG.DIRS_HOMEBREW?.length) return [];

		return this._pGetSourcesPrereleaseBrew({
			brewUtil: BrewUtil2,
			localSources: await Vetools.pGetLocalBrewSources(...this._CONFIG.DIRS_HOMEBREW),
			sources: await Vetools.pGetBrewSources(...this._CONFIG.DIRS_HOMEBREW),
			filterTypesLocalPartnered: [DataPipelineConsts.SOURCE_TYP_BREW_PARTNERED, DataPipelineConsts.SOURCE_TYP_BREW_LOCAL],
			filterTypesLocal: [DataPipelineConsts.SOURCE_TYP_BREW, DataPipelineConsts.SOURCE_TYP_BREW_LOCAL],
			filterTypesPartnered: [DataPipelineConsts.SOURCE_TYP_BREW_PARTNERED],
			filterTypes: [DataPipelineConsts.SOURCE_TYP_BREW],
			ClsDataPostLoader: this._CONFIG.ClsDataPostLoaderBrew,
		});
	}

	static async _pGetSourcesPrereleaseBrew (
		{
			localSources,
			sources,
			brewUtil,
			filterTypesLocalPartnered,
			filterTypesLocal,
			filterTypesPartnered,
			filterTypes,
			ClsDataPostLoader,
		},
	) {
		return [
			...localSources
				.map(({name, url, abbreviations, sourceJsons}) => {
					return new DataPipeline({
						name,
						filterTypes: sourceJsons.some(src => UtilPrereleaseBrewIndices.isPartneredSource(src))
							? [...filterTypesLocalPartnered]
							: [...filterTypesLocal],
												abbreviations,
						isWorldSelectable: true,

						dataSource: new DataSourceUrlPredefined(
							{
								url,
								brewUtil,
								isExistingPrereleaseBrew: true, 							},
						),
						DataPostLoader: ClsDataPostLoader,
					});
				}),

			...sources
				.map(({name, url, abbreviations, sourceJsons, status}) => {
					return new DataPipeline({
						name,
						filterTypes: sourceJsons.some(src => UtilPrereleaseBrewIndices.isPartneredSource(src))
							? [...filterTypesPartnered]
							: [...filterTypes],
						filterStatus: status,
						filterMisc: name?.startsWith("Sample - ") ? ["Sample"] : [],
						abbreviations,
						isWorldSelectable: true,

						dataSource: new DataSourceUrlPredefined(
							{
								url,
								brewUtil,
							},
						),
						DataPostLoader: ClsDataPostLoader,
					});
				}),
		];
	}
}

class DataSourceUtil {
	static getSourceFilterTypes (src) {
		if (SourceUtil.isPrereleaseSource(src)) {
			return [DataPipelineConsts.SOURCE_TYP_PRERELEASE];
		}

				if (UtilPrereleaseBrewIndices.isPartneredSource(src)) {
			return [DataPipelineConsts.SOURCE_TYP_BREW_PARTNERED];
		}

		return SourceUtil.isNonstandardSource(src)
			? [DataPipelineConsts.SOURCE_TYP_EXTRAS]
			: [DataPipelineConsts.SOURCE_TYP_OFFICIAL_SINGLE];
	}
}

