class ActivityBuilderNonPlayerBase extends ActivityBuilderBase {
}

class ActivityBuilderNonPlayerAttack extends ActivityBuilderNonPlayerBase {
	_activityType = "attack";
	_ClsState = EntryParseStateActivityModelAttack;

	async _pGetActivityStateMutEntry ({cpyEntry, stateInitial, hasAnyDamage, hasAnyHealing, statesHitherto}) {
		const state = this._getActivityState({cpyEntry, stateInitial});
		if (cpyEntry._featureExtras?.isAttack) return state;
		if (this._hasAnyRelevantState({state})) return state;
		return null;
	}

	_hasAnyRelevantState ({state}) {
		return state.attackAbility
			|| state.attackBonus;
	}
}

class ActivityBuilderNonPlayerSave extends ActivityBuilderNonPlayerBase {
	_activityType = "save";
	_ClsState = EntryParseStateActivityModelSave;

	async _pGetActivityStateMutEntry ({cpyEntry, stateInitial, hasAnyDamage, hasAnyHealing, statesHitherto}) {
		const state = this._getActivityState({cpyEntry, stateInitial});

		if (!this._hasAnyRelevantState({state})) return null;

		return state;
	}

	_hasAnyRelevantState ({state}) {
		return state.saveAbility?.length
		|| (state.saveDcCalculation && state.saveDcCalculation !== SAVE_DC_CALCULATION_CUSTOM_FORMULA)
		|| state.saveDcFormula;
	}
}

class _CompositeMutatorSaveBase extends CompositeMutatorBase {
	_activityType = "save";

	
	constructor (
		{
			expressionTransformer,
			...rest
		},
	) {
		super({...rest});
		this._expressionTransformer = expressionTransformer;
	}

	
	_hasExistingState ({state}) {
		return [
			"saveAbility",
			"saveDcCalculation",
			"saveDcFormula",
		]
			.some(prop => state[prop] !== undefined);
	}

	
	_mutApplySavingThrowActivityData ({state, savingThrowActivityData}) {
		const {
			saveAbility,
			saveDcCalculation,
			saveDcFormula,
		} = savingThrowActivityData;

		state.saveAbility = saveAbility;
		state.saveDcCalculation = saveDcCalculation;
		state.saveDcFormula = saveDcFormula;
	}
}

class CompositeMutatorSaveCreature extends _CompositeMutatorSaveBase {
	constructor (
		{
			sheetPb,
			spellAbility,
			...rest
		},
	) {
		super({...rest});
		this._sheetPb = sheetPb;
		this._spellAbility = spellAbility;
	}

	_mutateState ({cpyEntry, state}) {
		if (this._hasExistingState({state})) return;

		const savingThrowActivityData = UtilActivityBuilder.getSavingThrowActivityData({
			entries: cpyEntry.entries,
			expressionTransformer: this._expressionTransformer,
		});

		if (!savingThrowActivityData.isFoundParse || !this._sheetPb) return this._mutApplySavingThrowActivityData({state, savingThrowActivityData});

		if (Config.get("importCreatureFeature", "isPreferFlatSavingThrows")) return this._mutApplySavingThrowActivityData({state, savingThrowActivityData});

		const {activitySaveDcCalculation, activitySaveDcFormula} = savingThrowActivityData;

		if (activitySaveDcCalculation !== SAVE_DC_CALCULATION_CUSTOM_FORMULA) return this._mutApplySavingThrowActivityData({state, savingThrowActivityData});
		if (isNaN(activitySaveDcFormula)) return this._mutApplySavingThrowActivityData({state, savingThrowActivityData});

		const fromAbil = Number(activitySaveDcFormula) - this._sheetPb - 8;

				if (this._spellAbility) {
			const mod = Parser.getAbilityModNumber(Renderer.monster.getSafeAbilityScore(cpyEntry, UtilEntityCreatureFeature.getNamespacedProp(this._spellAbility)));
			if (mod === fromAbil) {
				return this._mutApplySavingThrowActivityData({
					state,
					savingThrowActivityData: {
						...savingThrowActivityData,
						saveDcCalculation: "spellcasting",
						saveDcFormula: "",
					},
				});
			}
		}

								for (const abil of ["cha", "wis", "int", "str", "dex", "con"]) {
			const mod = Parser.getAbilityModNumber(Renderer.monster.getSafeAbilityScore(cpyEntry, UtilEntityCreatureFeature.getNamespacedProp(abil)));
			if (mod === fromAbil) {
				return this._mutApplySavingThrowActivityData({
					state,
					savingThrowActivityData: {
						...savingThrowActivityData,
						saveDcCalculation: abil,
						saveDcFormula: "",
					},
				});
			}
		}

		return this._mutApplySavingThrowActivityData({state, savingThrowActivityData});
	}
}

class CompositeMutatorSaveVehicle extends _CompositeMutatorSaveBase {
	_mutateState ({cpyEntry, state}) {
		if (this._hasExistingState({state})) return;

		this._mutApplySavingThrowActivityData({
			state,
			savingThrowActivityData: UtilActivityBuilder.getSavingThrowActivityData({
				entries: cpyEntry.entries,
				expressionTransformer: this._expressionTransformer,
			}),
		});
	}
}

