class _ActionEntryParseState {
	constructor () {
		this.proficient = UtilItems.PROFICIENCY_LEVELS.AUTO;

		this.offensiveAbility = "none";
		this.activityIsAttackFlat = false;

		this.enchantmentBonus_number = 0;

		this._activityAttackBonus = 0;
	}

	
	getActivityAttackBonus () { return this._activityAttackBonus ? `${this._activityAttackBonus}` : ""; }

	setActivityAttackBonus (val) { this._activityAttackBonus = val; }

	addActivityAttackBonus (numOrStr) {
		if (typeof this._activityAttackBonus === "number" && typeof numOrStr === "number") {
			this._activityAttackBonus += numOrStr;
			return;
		}

		this._activityAttackBonus = [
			this._activityAttackBonus,
			numOrStr,
		]
			.join("+");
	}

	getSumWithActivityAttackBonus (num) {
		if (typeof this._activityAttackBonus === "number") return num + this._activityAttackBonus;
		return [
			num,
			this._activityAttackBonus,
		]
			.join("+");
	}
}

class _CompositeMutatorNonPlayerAttackBase extends CompositeMutatorBase {
	_activityType = "attack";

	_mode;
		_PropNamespacer;

		constructor (
		{
			isItemFvttTypeWeapon = false,
			sheetPb,
			pb,
			itemEntryWeapon = null,
			summonSpellLevel = null,
			...rest
		},
	) {
		super({...rest});

		this._isItemFvttTypeWeapon = isItemFvttTypeWeapon;
		this._sheetPb = sheetPb;
		this._pb = pb || 0; 		this._enchantmentBonus = itemEntryWeapon?.bonusWeapon && Number(itemEntryWeapon.bonusWeapon)
			? Number(itemEntryWeapon.bonusWeapon)
			: null;
		this._summonSpellLevel = summonSpellLevel;
	}

	
		_mutateState ({cpyEntry, state}) {
		const parseResult = this._getParsedActionEntryData({cpyEntry});

		state.attackAbility = parseResult.offensiveAbility;
		state.attackBonus = this._isItemFvttTypeWeapon
						? parseResult.activityAttackBonus
			: [
				parseResult.activityAttackBonus,
				parseResult.enchantmentBonus,
			]
				.filter(Boolean)
				.join(" + ");
		state.attackFlat = parseResult.activityIsAttackFlat;

		if (this._isItemFvttTypeWeapon) return;

						state.rangeValue = parseResult.rangeShort;
		state.rangeUnits = parseResult.rangeUnits;
	}

	
	getParsedActionEntryData ({cpyEntry}) {
		return this._getParsedActionEntryData({cpyEntry});
	}

	
	_getStrAttack ({cpyEntry}) {
		const strs = UtilWalker.getFlatStrs(cpyEntry.entries);

		return strs
			.find(str => /^\s*(?:{@atk |{@atkr )/.test(str));
	}

	_getParsedActionEntryData ({cpyEntry}) {
		const strAttack = this._getStrAttack({cpyEntry});
		if (!strAttack) return {};

		const parseState = new _ActionEntryParseState();
		if (this._mode === "creature") parseState.proficient = UtilItems.PROFICIENCY_LEVELS.PROFICIENT;
		else parseState.proficient = UtilItems.PROFICIENCY_LEVELS.NONE;

		const {rangeShort, rangeLong, rangeUnits} = this._getParsedActionEntryData_range({parseState, strAttack});

		this._getParsedActionEntryData_hit({cpyEntry, parseState, strAttack});

		return {
			rangeShort,
			rangeLong,
			rangeUnits,
			offensiveAbility: parseState.offensiveAbility,
			proficient: parseState.proficient,
			activityAttackBonus: parseState.getActivityAttackBonus(),
			activityIsAttackFlat: parseState.activityIsAttackFlat,
			enchantmentBonus: parseState.enchantmentBonus_number
				? `${parseState.enchantmentBonus_number}`
				: "",
		};
	}

	_getParsedActionEntryData_range ({parseState, strAttack}) {
		let rangeShort = null;
		let rangeLong = null;

				const mRange = /range (\d+)(?:\/(\d+))? ft/gi.exec(strAttack);
		if (mRange) {
			rangeShort = Number(mRange[1]);
			if (mRange[2]) rangeLong = Number(mRange[2]);
		} else {
			const mReach = /reach (\d+) ft/gi.exec(strAttack);
			if (mReach) {
				rangeShort = Number(mReach[1]);
			}
		}

		rangeShort = Config.getMetricNumberDistance({configGroup: this._configGroup, originalValue: rangeShort, originalUnit: "feet"});
		rangeLong = Config.getMetricNumberDistance({configGroup: this._configGroup, originalValue: rangeLong, originalUnit: "feet"});

		return {
			rangeShort,
			rangeLong,
			rangeUnits: rangeShort || rangeLong
				? Config.getMetricUnitDistance({configGroup: this._configGroup, originalUnit: "feet"})
				: null,
		};
	}

	_getParsedActionEntryData_hit ({cpyEntry, parseState, strAttack}) {
		if (/{@hitYourSpellAttack[} ]/gi.test(strAttack)) {
			parseState.proficient = UtilItems.PROFICIENCY_LEVELS.PROFICIENT;
			parseState.offensiveAbility = "none";
			parseState.setActivityAttackBonus(`+ @${SharedConsts.MODULE_ID_FAKE}.userchar.spellAttackRanged`);
			parseState.activityIsAttackFlat = true;
			return;
		}

						if (/\bautomatic hit\b/i.test(strAttack)) {
			parseState.proficient = UtilItems.PROFICIENCY_LEVELS.PROFICIENT;
			parseState.offensiveAbility = "none";
			parseState.setActivityAttackBonus(`+ 99`);
			parseState.activityIsAttackFlat = true;
			return;
		}

		const mHit = /{@hit (?<bonus>[^|}]+)(?:\|[^}]+)?}/gi.exec(strAttack);
		if (!mHit) return;

		const diceParseInfos = new DiceTagParserNonPlayer({
			expressionTransformer: new ExpressionTransformerNonPlayer(),
		})
			.getDiceTagParseInfos({str: strAttack});
		const [diceParseInfoPrime] = diceParseInfos;

		const {partsNonNumerical, totalNumerical: toHitNumerical} = UtilEntityGeneric.getProfBonusExpressionParts(mHit.groups.bonus);

						if (diceParseInfoPrime?.isFlatDamage()) {
			parseState.proficient = UtilItems.PROFICIENCY_LEVELS.PROFICIENT;
			parseState.offensiveAbility = "none";
			parseState.setActivityAttackBonus(toHitNumerical);
			parseState.activityIsAttackFlat = true;
			return;
		}

				if (this._enchantmentBonus == null || isNaN(this._enchantmentBonus)) {
			const mEnchantment = /(^|\b)\+(?<bonus>\d)(\b|$)/.exec(cpyEntry.name || "");
			parseState.enchantmentBonus_number = mEnchantment ? Number(mEnchantment.groups.bonus) : 0;
		} else {
			parseState.enchantmentBonus_number = this._enchantmentBonus;
		}

		const hitBonusFromAbil = toHitNumerical - parseState.enchantmentBonus_number - this._sheetPb;

				const mDamageBonus = /\s*(?<ptBonus>[-+]?\s*\d+)$/.exec((diceParseInfoPrime?.getBonusExpression() || "").trim());
		let damageBonusFromAbil;
		if (mDamageBonus) damageBonusFromAbil = Number(mDamageBonus.groups.ptBonus.replace(/\s+/g, "")) - parseState.enchantmentBonus_number;

						let assumedAbilMod = hitBonusFromAbil;
		if (damageBonusFromAbil != null && hitBonusFromAbil !== damageBonusFromAbil) {
			assumedAbilMod = damageBonusFromAbil;

						if (hitBonusFromAbil < damageBonusFromAbil) {
				parseState.proficient = UtilItems.PROFICIENCY_LEVELS.NONE;
			} else {
												parseState.setActivityAttackBonus(hitBonusFromAbil - damageBonusFromAbil);
			}
		}

				let isFoundOffensiveAbility = false;
				for (const abil of ["str", "dex", "cha", "wis", "int", "con"]) {
			const kNamespaced = this._PropNamespacer.getNamespacedProp(abil);

			if (cpyEntry[kNamespaced] == null) continue;

			const mod = Parser.getAbilityModNumber(Renderer.monster.getSafeAbilityScore(cpyEntry, kNamespaced));
			if (mod === assumedAbilMod) {
				parseState.offensiveAbility = abil;
				isFoundOffensiveAbility = true;
				break;
			}
		}

								if (partsNonNumerical.length) {
			parseState.setActivityAttackBonus(
								new ExpressionTransformerNonPlayer({
					summonSpellLevel: this._summonSpellLevel,
					offensiveAbility: parseState.offensiveAbility,
				})
					.getTransformedExpression(mHit.groups.bonus),
			);
			parseState.activityIsAttackFlat = true;
			return;
		}

		const offensiveAbilityModNumber = parseState.offensiveAbility === "none"
			? 0
			: Parser.getAbilityModNumber(
				Renderer.monster.getSafeAbilityScore(cpyEntry, this._PropNamespacer.getNamespacedProp(parseState.offensiveAbility)),
			);

										if (!isFoundOffensiveAbility && this._pb) {
									const curCalcBonus = parseState.getSumWithActivityAttackBonus(this._pb + offensiveAbilityModNumber);

			if (curCalcBonus !== toHitNumerical) {
				const delta = toHitNumerical - curCalcBonus;
				parseState.addActivityAttackBonus(delta);
			}

			return;
		}

						if (parseState.proficient === UtilItems.PROFICIENCY_LEVELS.NONE) {
			const curCalcBonus = parseState.getSumWithActivityAttackBonus(offensiveAbilityModNumber);
			if (curCalcBonus === toHitNumerical) return;

			const delta = toHitNumerical - curCalcBonus;
			parseState.addActivityAttackBonus(delta);

															if (!this._isItemFvttTypeWeapon) parseState.activityIsAttackFlat = true;
		}
	}
}

