class CharactermancerFeatureSubCompManagerBase {
	_CompClass;
	_prop;
	_propFormDatas;
	_title = null;

	constructor (
		{
			actor,
			featureSourceTracker,
			additionalSpellsSourceTracker,
			availableProficiencyManager,
			eventChannelRenderResize = null,
		},
	) {
		this._actor = actor;
		this._featureSourceTracker = featureSourceTracker;
		this._additionalSpellsSourceTracker = additionalSpellsSourceTracker;
		this._availableProficiencyManager = availableProficiencyManager;
		this._eventChannelRenderResize = eventChannelRenderResize;

		this._subComps = [];
		this._prevSubComps = [];
	}

	
	_getMappedProficiencies (profs) {
		return profs;
	}

	
	async _pHasEntryData (optionsSet, {isRequireChoice = false} = {}) {
		for (const loaded of optionsSet) {
			const {entity} = loaded;

			const proficiencies = entity?.[this._prop] || entity?.entryData?.[this._prop];
			if (!proficiencies) continue;

			const proficienciesMapped = this._getMappedProficiencies(proficiencies);

			if (!isRequireChoice) return true;

			const isNoChoice = this._CompClass.isNoChoice(
				proficienciesMapped,
				{
					availableProficiencyManager: this._availableProficiencyManager,
				},
			);
			if (!isNoChoice) return true;
		}
		return false;
	}

	async pIsForceDisplay (optionsSet) {
		return this._pHasEntryData(optionsSet);
	}

	async pIsAvailable (optionsSet) {
		return this._pHasEntryData(optionsSet);
	}

	async pHasSubChoice (optionsSet) {
		return this._pHasEntryData(optionsSet, {isRequireChoice: true});
	}

	
	setPrevSubCompsFrom (other) {
		this._prevSubComps = other._subComps;
	}

	
	async _pGetFormDatas (
		{
			cpySelectedLinkedEntityInfos,
		},
	) {
		const out = [];

		for (let i = 0; i < cpySelectedLinkedEntityInfos.length; ++i) {
			const linkedEntityInfo = cpySelectedLinkedEntityInfos[i];

			const {entity} = linkedEntityInfo;

			if ((entity?.[this._prop] || entity?.entryData?.[this._prop]) && this._subComps[i]) {
				const formData = await this._subComps[i].pGetFormData();
				out.push(formData);
			}
		}

		return out;
	}

	async pGetWrappedFormDatas (
		{
			cpySelectedLinkedEntityInfos,
			isSkipCharactermancerHandled = false,
		},
	) {
		if (isSkipCharactermancerHandled) {
			return {[this._propFormDatas]: []};
		}

		return {[this._propFormDatas]: await this._pGetFormDatas({cpySelectedLinkedEntityInfos})};
	}

	
		_setComp (
		{
			ix,
			entity,
		},
	) {
		throw new Error("Unimplemented!");
	}

	async _pInitSubComp (
		{
			ix,
			selectedLinkedEntityInfos,
		},
	) {
		this._subComps[ix] = null;
		if (!(await this.pIsAvailable([selectedLinkedEntityInfos[ix]]))) return;

		const {entity} = selectedLinkedEntityInfos[ix];

		if (!entity?.[this._prop] && !entity?.entryData?.[this._prop]) return;

		this._setComp({
			ix,
			entity,
		});

				if (this._prevSubComps?.[ix]) {
			this._subComps[ix]._proxyAssignSimple("state", MiscUtil.copyFast(this._prevSubComps[ix].__state));
		}
	}

	async pNotRender (
		{
			ix,
			selectedLinkedEntityInfos,
		},
	) {
		await this._pInitSubComp({
			ix,
			selectedLinkedEntityInfos,
		});

		if (!this._subComps[ix]) return;

		if (this._subComps[ix].pNotRender) await this._subComps[ix].pNotRender();
	}

	async pRender (
		{
			ix,
			$stgSubChoiceData,
			selectedLinkedEntityInfos,
			ptrIsFirstSection,
		},
	) {
		await this._pInitSubComp({
			ix,
			selectedLinkedEntityInfos,
		});

		if (!(await this.pIsForceDisplay([selectedLinkedEntityInfos[ix]]))) return;

		const title = this._title || this._subComps[ix]?.modalTitle;

		if (title) $stgSubChoiceData.append(`${ptrIsFirstSection._ ? "" : `<div class="w-100 mt-1 mb-2"></div>`}<div class="bold mb-2">${title}</div>`);

		if (this._subComps[ix].pRender) await this._subComps[ix].pRender($stgSubChoiceData);
		else this._subComps[ix].render($stgSubChoiceData);

		ptrIsFirstSection._ = false;
	}

	
	postRenderLoop () {
		this._prevSubComps = null;
	}

	
	renderLoopStatic () {
		this._subComps = [];
	}

	
	unregisterSourceTracking ({featureSourceTracker, additionalSpellsSourceTracker}) {
		this._subComps
			.filter(Boolean)
			.forEach(comp => {
				if (featureSourceTracker) featureSourceTracker.unregister(comp);
				if (additionalSpellsSourceTracker) additionalSpellsSourceTracker.unregister(comp);
			});
	}
}

class CharactermancerFeatureSubCompManagerProficiencyOtherBase extends CharactermancerFeatureSubCompManagerBase {
	_propPathActorExistingProficiencies = null;

	
	_getExistingProficienciesFvtt () {
		if (!this._propPathActorExistingProficiencies) throw new Error(`No FVTT prop path defined!`);
		return {[this._prop]: MiscUtil.get(this._actor, ...this._propPathActorExistingProficiencies)};
	}

	
	_setComp (
		{
			ix,
			entity,
		},
	) {
		const availableRaw = entity[this._prop] || entity.entryData[this._prop];
		const existingFvtt = this._getExistingProficienciesFvtt();
		this._subComps[ix] = new this._CompClass({
			featureSourceTracker: this._featureSourceTracker,
			additionalSpellsSourceTracker: this._additionalSpellsSourceTracker,
			existing: this._CompClass.getExisting(existingFvtt, {availableProficiencyManager: this._availableProficiencyManager}),
			existingFvtt,
			available: this._getMappedProficiencies(availableRaw),
			availableProficiencyManager: this._availableProficiencyManager,
			eventChannelRenderResize: this._eventChannelRenderResize,
		});
	}
}

