class EquipmentUtilCost {
	static isUseRarityValue () {
		return VetoolsConfig$1.get("styleSwitcher", "style") === SITE_STYLE__ONE
			&& Config.get("equipmentShop", "isUseRarityPricing");
	}

	
	static getItemCost (item, {isUseRarityValue = null} = {}) {
		isUseRarityValue ??= this.isUseRarityValue();

		const valueBase = UtilEntityItem.getItemValue({item, isUseRarityValue}) || 0;
		return valueBase * Config.get("equipmentShop", "priceMultiplier");
	}

	static getItemDisplayListCostInfo (item, {isUseRarityValue = null} = {}) {
		isUseRarityValue ??= this.isUseRarityValue();

		const optsValue = {isShortForm: true, multiplier: Config.get("equipmentShop", "priceMultiplier")};

		const fromValue = Parser.itemValueToFullMultiCurrency(item, optsValue);
		if (fromValue) return {text: fromValue, isFromRarity: false};

		if (!UtilDocumentItemItem.isUseRarityValue()) return {text: fromValue, isFromRarity: false};

		return {
			text: Parser.itemValueToFullMultiCurrency({value: UtilEntityItem.getItemValue({item, isUseRarityValue}), currencyConversion: item.currencyConversion}, optsValue),
			isFromRarity: true,
		};
	}
}

class ModalFilterEquipment extends ModalFilterBase {
	static _$getFilterColumnHeaders (btnMeta) {
		return super._$getFilterColumnHeaders(btnMeta).map($btn => $btn.addClass(`ve-btn-5et`));
	}

	constructor (compStartingEquipment) {
		super({
			pageFilter: new PageFilterItems({
				filterOpts: {
					"Category": {
						deselFn: (it) => it === "Generic Variant",
					},
				},
			}),
			namespace: "ImportListCharacter_modalFilterEquipment",
			sortByInitial: "type",
		});
		this._compParent = compStartingEquipment;
	}

	_$getColumnHeaders () {
		const btnMeta = [
			{sort: "name", text: "Name", width: "3-2"},
			{sort: "type", text: "Type", width: "3-2"},
			{sort: "cost", text: "Cost", width: "1-8"},
			{sort: "source", text: "Source", width: "1-8"},
		];
		return this.constructor._$getFilterColumnHeaders(btnMeta);
	}

	async _pLoadAllData () { return []; }

	_$getWrpList () { return $(`<div class="veapp__list mb-1 h-100 min-h-0"></div>`); }

	_$getColumnHeaderPreviewAll (opts) {
		return super._$getColumnHeaderPreviewAll(opts).addClass(["ve-btn-5et", "ve-muted"]);
	}

	_getListItem (pageFilter, item, itI) {
		if (item.noDisplay) return null;

		const isUseRarityValue = EquipmentUtilCost.isUseRarityValue();

		Renderer.item.enhanceItem(item);
		pageFilter.mutateAndAddToFilters(item);

		const eleRow = document.createElement("div");
		eleRow.className = "px-0 w-100 veapp__list-row ve-flex-col no-shrink";

		const hash = UrlUtil.URL_TO_HASH_BUILDER[UrlUtil.PG_ITEMS](item);
		const source = Parser.sourceJsonToAbv(item.source);
		const type = item._textTypes.join(", ");
		const costInfo = EquipmentUtilCost.getItemDisplayListCostInfo(item, {isUseRarityValue});

		eleRow.innerHTML = `<div class="w-100 veapp__list-row-hoverable ve-flex-v-center">
			<div class="ve-col-1 ve-flex-vh-center">
				<div class="ui-list__btn-inline" title="Toggle Preview (SHIFT to Toggle Info Preview)">${ListUiUtil.HTML_GLYPHICON_EXPAND}</div>
			</div>

			<span class="ve-col-3-2">${item.name}</span>
			<span class="ve-col-3-2">${item._textTypes.join(", ").toTitleCase()}</span>
			<span class="ve-col-1-8 ve-text-right px-1 ${costInfo.isFromRarity ? "italic ve-muted" : ""}" ${costInfo.isFromRarity ? `title="Price based on item rarity"` : ""}>${costInfo.text.replace(/ +/g, "\u00A0")}</span>
			<span class="ve-col-1-8 ve-text-center ${Parser.sourceJsonToSourceClassname(item.source)} pr-0" title="${Parser.sourceJsonToFull(item.source)}">${source}</span>
			<div class="ve-col-1 ve-flex-vh-center ve-btn-group">
				<button class="ve-btn ve-btn-5et ve-btn-xxs ve-btn-default" title="Add (SHIFT to add 5; CTRL to ignore price)"><span class="glyphicon glyphicon-plus"></span></button>
				<button class="ve-btn ve-btn-5et ve-btn-xxs ve-btn-default" title="Remove (SHIFT to remove 5; CTRL to ignore price)"><span class="glyphicon glyphicon-minus"></span></button>
			</div>
		</div>`;

		const btnShowHidePreview = eleRow.firstElementChild.firstElementChild.firstElementChild;
		btnShowHidePreview.addEventListener("click", evt => {
			evt.stopPropagation();
			evt.preventDefault();

			const elePreviewWrp = ListUiUtil.getOrAddListItemPreviewLazy(listItem);

			ListUiUtil.handleClickBtnShowHideListPreview(
				evt,
				UrlUtil.PG_ITEMS,
				item,
				btnShowHidePreview,
				elePreviewWrp,
			);
		});

		const listItem = new ListItem(
			itI,
			eleRow,
			item.name,
			{
				hash,
				source,
				sourceJson: item.source,
				cost: EquipmentUtilCost.getItemCost(item, {isUseRarityValue}),
				type,
			},
			{
				btnAdd: eleRow.firstElementChild.lastElementChild.firstElementChild,
				btnSubtract: eleRow.firstElementChild.lastElementChild.lastElementChild,
				btnShowHidePreview,
			},
		);

		return listItem;
	}

	setDataList (itemDatas) {
		this._list.removeAllItems();

		const isUseRarityValue = EquipmentUtilCost.isUseRarityValue();

		this._allData = (itemDatas || [])
			.filter(ent => {
				if (UtilEntityItem.isTreasureItem(ent)) return false;
				if (ent.value != null) return true;

				if (
					ent._valueFromRarity != null
					&& isUseRarityValue
				) return true;

				return false;
			});

		this._allData.forEach((it, i) => {
			this._pageFilter.mutateAndAddToFilters(it);

			const filterListItem = this._getListItem(this._pageFilter, it, i);
			this._list.addItem(filterListItem);

			const itemUid = `${it.name}|${it.source}`;

			const onClickAdd = evt => {
				evt.preventDefault();
				evt.stopPropagation();

				const isIgnoreCost = EventUtil.isCtrlMetaKey(evt);

				if (evt.shiftKey) this._compParent.addBoughtItem(itemUid, {quantity: 5, isIgnoreCost});
				else this._compParent.addBoughtItem(itemUid, {isIgnoreCost});
			};

			const onClickSubtract = evt => {
				evt.preventDefault();
				evt.stopPropagation();

				const isIgnoreCost = EventUtil.isCtrlMetaKey(evt);

				if (evt.shiftKey) this._compParent.subtractBoughtItem(itemUid, {quantity: 5, isIgnoreCost});
				else this._compParent.subtractBoughtItem(itemUid, {isIgnoreCost});
			};

			e_({ele: filterListItem.ele})
				.onn("click", evt => onClickAdd(evt))
				.onn("contextmenu", evt => onClickSubtract(evt));

			e_({ele: filterListItem.data.btnAdd})
				.onn("click", evt => onClickAdd(evt))
				.onn("contextmenu", evt => onClickSubtract(evt));

			e_({ele: filterListItem.data.btnSubtract})
				.onn("click", evt => onClickSubtract(evt))
				.onn("contextmenu", evt => onClickAdd(evt));
		});

						this._pageFilter.sourceFilter.setFromValues({"Source": {}});

		this._pageFilter.filterBox.render();
		this._list.update();
		this._handleFilterChange();
	}
}

