		if (this._additionalSpellsSourceTracker) this._additionalSpellsSourceTracker.addHook(this, "pulseSpellsAlwaysPrepared", hkAlwaysPreparedSpells);
		hkAlwaysPreparedSpells();
		
				const hkExpandedSpells = () => this.handleFilterChange();
