class NoteImageCreator {
	static _COLOR_TEXT = "#010101";

	static _PATH_DIR = "puck";

	
	static _urlCache = null;

	static async pBuildCache () {
		this.flushCache();

		const {
			dirListing,
			isDirExists,
			isError,
		} = await VetoolsSaverImages.pGetDirectoryListing({path: this._PATH_DIR, isDirPath: true});

		if (!isDirExists || isError) return;

		dirListing?.files
			.forEach(fileUri => {
				const filePath = UtilFileBrowser.decodeUrl(fileUri);
				const name = filePath.split("/").last().split(".").slice(0, -1).join(".");
				this._urlCache[name] = filePath;
			});
	}

	static flushCache () { this._urlCache = {}; }

	static _getCachedUrl ({name}) {
		return this._urlCache?.[name];
	}

	static _addCacheUrl ({name, url}) {
		(this._urlCache ||= {})[name] = url;
	}

	
	static async pCreateImageGetUrl ({name}) {
		if (!name) throw new Error(`No puck name provided!`);

		const cachedUrl = this._getCachedUrl({name});
		if (cachedUrl) return cachedUrl;

		const img = await this._pGetBlankPuckImage();
		const tokenBlob = await this._pGetPuckBlob({name, img});
		const url = await VetoolsSaverImages.pSaveImageToServerAndGetUrl({blob: tokenBlob, path: `${this._PATH_DIR}/${name}.webp`});

		this._addCacheUrl({name, url});

		return url;
	}

	static async _pGetBlankPuckImage () {
		return UtilImage.pLoadTempImage(`modules/${SharedConsts.MODULE_ID}/media/img/puck.png`, {isCacheable: true});
	}

	static _pGetPuckBlob ({name, img}) {
		return UtilImage.pDrawTextGetBlob({
			text: name,
			img,
			color: NoteImageCreator._COLOR_TEXT,
			font: `"Times New Roman", Times, serif`,
			fontSizeRatio: 0.4,
						fontVerticalOffsetRatio: 1 / 11,
			isBold: true,
		});
	}
}

