	static _getNullJoinedToolsList ({toolsList}) {
		let isLastNull = true; 
		toolsList = toolsList
			.filter(menuToolInfo => {
				if (menuToolInfo != null) {
					isLastNull = false;
					return true;
				}

				if (isLastNull) return false;

				isLastNull = true;

				return true;
			});

		if (!toolsList.length) return toolsList;

				return toolsList.at(-1) == null ? toolsList.slice(0, -1) : toolsList;
	}

	static _getFilteredToolsList ({toolsList}) {
		toolsList = toolsList
			.filter(menuToolInfo => {
				if (menuToolInfo == null) return true;
				return menuToolInfo.isVisibleForUser();
			});

		toolsList = this._getNullJoinedToolsList({toolsList});

		if (!toolsList.length) {
			return [
				new MenuToolInfo({
					name: `<i class="ve-muted" title="They may be disabled${game.user.isGM ? ` in your Config` : `, or you may have insufficient permissions`}.">No options available!</i>`,
					pFnOnClick: () => {  },
					iconClass: "fas fa-do-not-enter ve-muted",
				}),
			];
		}

		return toolsList;
	}
