class SidebarUi {
	static _isAddDirectoryWrappers () {
		return game.user.role >= Config.get("import", "minimumRoleDirectory");
	}

	static preInit () {
		if (this._isAddDirectoryWrappers()) this._init_addDirectoryWrappers();
		this._init_addCompendiumObfuscation();
	}

	static _init_addDirectoryWrappers () {
		this._init_pAddDirectoryWrapper("renderSceneDirectory");
		this._init_pAddDirectoryWrapper("renderActorDirectory");
		this._init_pAddDirectoryWrapper("renderItemDirectory");
		this._init_pAddDirectoryWrapper("renderJournalDirectory");
		this._init_pAddDirectoryWrapper("renderRollTableDirectory");
		this._init_pAddDirectoryWrapper("renderCardsDirectory");
		this._init_pAddDirectoryWrapper("renderMacroDirectory");
		this._init_pAddDirectoryWrapper("renderCompendiumDirectory");
	}

	static _init_addCompendiumObfuscation () {
		Hooks.on("renderCompendiumDirectory", () => {
			if (!Config.get("ui", "isStreamerMode")) return;

			$(`#compendium`).find(`.compendium-footer .source`).each((i, e) => {
				[...e.childNodes || []]
					.filter(node => (node?.textContent || "").trim() === SharedConsts.MODULE_ID)
					.forEach(node => node.textContent = ` ${SharedConsts.MODULE_ID_FAKE}`);
			});
		});
	}

		static _init_pAddDirectoryWrapper (hookName) {
		const minRole = Config.get("import", "minimumRole");

		const isAddImportButton = game.user.role >= minRole && ChooseImporter.isImportableFvttEntityHook(hookName);

		Hooks.on(hookName, (app, html) => {
			if (html instanceof $) html = html[0];

			[...html.querySelectorAll(`.dir__wrp-header`)].forEach(ele => ele.remove());

			const $btnImport = ChooseImporter.$getDirButton(hookName);
			const $btnQuick = ChooseImporter.$getDirButtonQuick(hookName);

			const $ptBtnsImport = isAddImportButton ? $$`<div class="ve-btn-group ve-flex-v-center mr-1 w-100">
				${$btnImport ? $btnImport.addClass(`dir__btn-header`) : null}
				${$btnQuick ? $btnQuick.addClass(`dir__btn-header`) : null}
			</div>` : `<div class="w-100"></div>`;

			const $wrp = $$`<div class="ve-flex-col dir__wrp-header w-100 no-shrink min-w-100 dir__control-header ${this._init_isRequireExtraSpacingFvttEntityType(hookName) ? "pb-1" : ""}">
				<div class="ve-flex w-100">
					${$ptBtnsImport}
					${MenuCollectionTools.$getDirButton(hookName).addClass(`dir__btn-header`)}
					${ConfigUiDirectory.$getDirButton().addClass(`dir__btn-header`)}
				</div>
			</div>`;

						const eleInsertAfterTarget = html.querySelector(`.header-actions`);
			if (eleInsertAfterTarget) $wrp.insertAfter(eleInsertAfterTarget);

			MenuCollectionTools.$getDirButton(hookName)
				.addClass(`dir__btn-header dir__control-header--alt`)
				.css({maxWidth: 28})
				.appendTo(html.querySelector(`.header-actions.action-buttons`));
		});
	}

	static _init_isRequireExtraSpacingFvttEntityType (hookName) {
		return ["renderMacroDirectory", "renderCompendiumDirectory", "renderCardsDirectory"].includes(hookName);
	}
}

