class MenuTitle extends Menu {
	static _HOOK_NAME = null;
	static _EVT_NAMESPACE = null;
	static _TOOL_LIST = [];
	static _DOCUMENT_GENERIC_CLASS = null;

		static init () {
		if (!this._HOOK_NAME) throw new Error(`Missing hook name!`);
		if (!this._TOOL_LIST.length) return; 
		Hooks.on(this._HOOK_NAME, (app, buttons) => {
			const availableTools = this._TOOL_LIST
				.filter(toolMeta => !toolMeta.isRequireOwner() || UtilMigrate.isOwner(app.document));

			const menu = new this(this._EVT_NAMESPACE, availableTools);
			menu._doAddButtonSheet(app, buttons);
		});
	}

		static onHookTidy5eSheetReady (api) {
		if (!this._DOCUMENT_GENERIC_CLASS) return;

						const methodName = `register${this._DOCUMENT_GENERIC_CLASS.name}HeaderControls`;
		if (!api[methodName]) return;

		const controls = this._getToolsListAppV2Controls();

		api[methodName]({
			controls: controls,
		});
	}
	
	
	static _getToolsListAppV2Controls ({app} = {}) {
		return this._TOOL_LIST
			.map(toolMeta => {
				return {
					icon: toolMeta.getIconClass(),
					label: toolMeta.getDisplayName(),

										onClick: (evt) => {
						return toolMeta.pHandleOpenButtonClick(evt, app);
					},

															onClickAction: function (evt, tgt) {
						return toolMeta.pHandleOpenButtonClick(evt, this);
					},

																														position: "menu",
					
										visible: function () {
						return toolMeta.isVisibleForApp(this)
							&& toolMeta.isVisibleForUser();
					},

					ownership: toolMeta.isRequireOwner()
						? CONST.DOCUMENT_OWNERSHIP_LEVELS.OWNER
						: CONST.DOCUMENT_OWNERSHIP_LEVELS.NONE,
				};
			});
	}

	
	constructor (eventNamespace, toolsList) {
		if (!eventNamespace) throw new Error(`Missing namespace argument!`);
		if (!toolsList) throw new Error(`Missing tools list argument!`);

		toolsList = Menu._getFilteredToolsList({toolsList});

		super({
			eventNamespace,
			toolsList,
			direction: "down",
		});
	}

	_doAddButtonSheet (app, buttons) {
		if (Config.get("ui", "isHidePlutoniumSheetMenuButton")) return;

		if (app instanceof foundry.applications.api.ApplicationV2) return this._doAddButtonSheet_appV2(app, buttons);
		return this._doAddButtonSheet_appV1(app, buttons);
	}

	_doAddButtonSheet_appV2 (app, buttons) {
		buttons.push(
			...this.constructor._getToolsListAppV2Controls({app}),
		);
	}

	_doAddButtonSheet_appV1 (app, buttons) {
		const isUseDefaultStyling = app.options?.classes?.includes("dnd5e2");

		buttons.splice(
			buttons.length - 1,
			0,
			{
				class: "tit-menu__btn-open--sheet",
				icon: `fas fa-fw fa-ellipsis-vertical ${isUseDefaultStyling ? "" : "mr-0"}`,
				label: isUseDefaultStyling
					? `${Config.get("ui", "isStreamerMode") ? "Other" : "Plutonium"} Options`
					: null,
				_plut_buttonSheetHeader: true,
				onclick: evt => this._pOpenMenu(evt, app),
			},
		);
	}
}

