class Patcher_GameKeyboard {
	static _ACTION_DISMISS = "KEYBINDINGS.Dismiss";
	static _ELEMENTS_WITH_FOCUS = new Set(["INPUT", "TEXTAREA"]);
	static _LOCK_EDIT_KEYBINDS = new VeLock();
	static _LAST_KEYBOARD_CONTEXT = null;

	static prePreInit () {
		this._init_registerKeybindEsc();
	}

	static init () {
		Hooks.on(`${SharedConsts.MODULE_ID_FAKE}.configUpdate`, () => this._pHandleConfigUpdate());
		this._pHandleConfigUpdate();

		this._init_patchEscapeMethods();
	}

	static _init_patchEscapeMethods () {
						UtilLibWrapper.addPatch(
			"game.keyboard._processKeyboardContext",
			this._lw_game_keyboard__processKeyboardContext,
			UtilLibWrapper.LIBWRAPPER_MODE_WRAPPER,
		);
		
		UtilLibWrapper.addPatch(
			"game.keyboard.hasFocus",
			this._lw_game_keyboard_hasFocus,
			UtilLibWrapper.LIBWRAPPER_MODE_WRAPPER,
		);
	}

	static _lw_game_keyboard__processKeyboardContext (fn, ...args) {
		const val = fn(...args);
		Patcher_GameKeyboard._LAST_KEYBOARD_CONTEXT = args[0];
		return val;
	}

	static _lw_game_keyboard_hasFocus (fn, ...args) {
		const val = fn(...args);
		if (!Config.get("ui", "isFixEscapeKey")) return val;
		if (Patcher_GameKeyboard._LAST_KEYBOARD_CONTEXT?.key !== "Escape") return val;
				return false;
	}

	static async _pHandleConfigUpdate () {
		try {
			await Patcher_GameKeyboard._LOCK_EDIT_KEYBINDS.pLock();
			await this._pHandleConfigUpdate_();
		} finally {
			Patcher_GameKeyboard._LOCK_EDIT_KEYBINDS.unlock();
		}
	}

	static async _pHandleConfigUpdate_ () {
						game.keybindings.set(SharedConsts.MODULE_ID, Patcher_GameKeyboard._ACTION_DISMISS);
		if (!Config.get("ui", "isFixEscapeKey")) return;
		game.keybindings.set(SharedConsts.MODULE_ID, Patcher_GameKeyboard._ACTION_DISMISS, [{key: "Escape"}]);
	}

	static _init_registerKeybindEsc () {
		game.keybindings.register(
			SharedConsts.MODULE_ID,
			Patcher_GameKeyboard._ACTION_DISMISS,
			{
				name: "KEYBINDINGS.Dismiss",
				hint: `An improved version of Foundry's built-in binding. Bind the "Escape" key to (in this order): de-select active input fields; de-select selected canvas elements; close context menus; close individual windows in most-recently-active-first order; toggle the main menu.`,
				onDown: async (context) => {
					const {event} = context;

										if (UiUtil._MODAL_STACK && UiUtil._MODAL_STACK.length) return true;

										if (ui.menu?.rendered) {
						await ui.menu.toggle();
						return true;
					}

										if (document.hasFocus() && Patcher_GameKeyboard._ELEMENTS_WITH_FOCUS.has(event.target.nodeName)) {
						event.target.blur();
						return true;
					}

										if (canvas.currentMouseManager) {
						canvas.currentMouseManager.interactionData.cancelled = true;
						canvas.currentMouseManager.cancel();
						return true;
					}

										if (canvas.ready) canvas.fog.commit();

										if (ui.context?.element) {
						await ui.context.close();
						return true;
					}

										if (foundry.nue.Tour.tourInProgress) {
						foundry.nue.Tour.activeTour.exit();
						return true;
					}

										if (Menu.closeAllMenus()) {
						return true;
					}

															if (game.view === "game" && canvas.activeLayer instanceof foundry.canvas.layers.InteractionLayer) {
						if (canvas.activeLayer._onDismissKey(context.event)) return true;
					}

															const appsOpen = UtilApplications.getOpenAppsSortedByZindex({isFilterInvalid: true})
						.filter(app => {
							if (app.isEscapeable != null && !app.isEscapeable) return false;

							if (
								UtilCompat.isSimpleCalendarActive()
								&& IntegrationSimpleCalendar.isSimpleCalendarApp(app)
								&& IntegrationSimpleCalendar.isPersistentOpen()
							) return false;

							if (
								UtilCompat.isModulTerrainHeightToolsActive()
								&& IntegrationTerrainHeightTools.isTerrainStackViewerApp(app)
							) return false;

							if (
								UtilCompat.isMonksCombatDetailsActive()
								&& IntegrationMonksTokenBar.isIgnoreWindowCloseEsc(app)
							) return false;

							if (
								UtilCompat.isMonksTokenBarActive()
								&& IntegrationMonksTokenBar.isIgnoreWindowCloseEsc(app)
							) return false;

							return true;
						});
					if (appsOpen.length) {
												while (appsOpen.length) {
							const app = appsOpen.pop();
							const isClosedPlut = await app.close({closeKey: true});
														if (isClosedPlut || !app.rendered) return true;
						}
					}

										ui.menu.toggle();

										if (canvas.ready) await canvas.fog.save();

					return true;
				},
				restricted: false,
				precedence: CONST.KEYBINDING_PRECEDENCE.PRIORITY,
			},
		);
	}
}

class Patcher_ActiveEffectConfig {
	static init () {
		UtilLibWrapper.addPatch(
			"foundry.applications.sheets.ActiveEffectConfig.prototype._initializeApplicationOptions",
			this._lw_ActiveEffectConfig_prototype__initializeApplicationOptions,
			UtilLibWrapper.LIBWRAPPER_MODE_WRAPPER,
		);

		Hooks.on("renderActiveEffectConfig", (app, html, opts) => {
			this._onHookActiveEffectConfig(app, html, opts);
		});
	}

	static _lw_ActiveEffectConfig_prototype__initializeApplicationOptions (fn, ...args) {
		const base = fn(...args);
		if (!Config.get("actor", "isUseExtendedActiveEffectsParser")) return base;
		base.position.width = 640;
		base.window.resizable = true;
		return base;
	}

	static _onHookActiveEffectConfig (app, html, opts) {
		if (!Config.get("ui", "isExpandActiveEffectConfig") || UtilCompat.isDaeActive()) return;

				const wrpTabChanges = es(`[data-application-part="changes"]`, html);

		const [eleRowHeader, eleListChanges] = wrpTabChanges.children;

														eleRowHeader.style.gridTemplateColumns = eleListChanges.style.gridTemplateColumns = "2rem 12rem 7rem 1fr 4rem 1rem";

		eleRowHeader.prepend(ee`<div></div>`);

		em(`[data-index]`, eleListChanges)
			.forEach(row => {
				const $row = $(row);

				const $iptKey = $row.find(`.key input`);
				const $selMode = $row.find(`.mode select`);
				const $iptValue = $row.find(`.value input`);

				$(`<button class="no-grow no-shrink ve-text-center p-0 m-0 aeff__btn-inline" title="Find Active Effect Attribute Key"><i class="fas fa-fw fa-magnifying-glass mr-0"></i></button>`)
					.click(async evt => {
						evt.preventDefault();
						evt.stopPropagation();

						const availableEffectsDoc = UtilActiveEffects.getAvailableEffects(app.document.parent, opts);
																		const availableEffectsActor = (Dnd5eUtil.isDnd5e() && app.document.parent instanceof Item)
							? UtilActiveEffects.getAvailableEffects(
																new CONFIG.Actor.documentClass({name: "Temp", type: "character"}),
								{isActorEffect: true},
							)
							: [];
						const availableEffectsAll = [
							...availableEffectsDoc,
							...availableEffectsActor,
						]
							.unique(it => it.path);

						const {$modalInner, doClose, doAutoResize} = await UtilApplications.pGetShowApplicationModal({
							title: `Find Active Effect Attribute Key`,
							isWidth100: true,
							isHeight100: true,
						});

						const $iptSearch = $(`<input type="search" class="search w-100 form-control h-initial" placeholder="Find keys...">`);
						const $btnReset = $(`<button class="ve-btn ve-btn-5et veapp__btn-list-reset" name="btn-reset">${game.i18n.localize("PLUT.Reset")}</button>`)
							.click(() => list.reset());
						const $wrpBtnsSort = $$`<div class="ve-flex-v-stretch input-group input-group--bottom mb-1">
							<button class="ve-btn ve-btn-5et ve-col-4-5 sort" data-sort="name">Name</button>
							<button class="ve-btn ve-btn-5et ve-col-2-5 sort" data-sort="value">Current Value</button>
							<button class="ve-btn ve-btn-5et ve-col-2-5 sort" data-sort="baseValue" title="The underlying value, without any current effects/etc. applied.">Current Base Value</button>
							<button class="ve-btn ve-btn-5et ve-col-2-5 sort" data-sort="default">Default Value</button>
						</div>`;
						const $wrpList = $(`<div class="veapp__list h-100 mb-1"></div>`);

						const list = new List({
							isUseJquery: true,
							$iptSearch,
							$wrpList,
						});

						SortUtil.initBtnSortHandlers($wrpBtnsSort, list);

						availableEffectsAll.forEach((ae, ix) => {
							const val = MiscUtil.get(app.document.parent.system, ...ae.path.split("."));
							const _val = MiscUtil.get(app.document.parent.system._source, ...ae.path.split("."));

							const $ele = $$`<label class="ve-flex w-100 veapp__list-row clickable veapp__list-row-hoverable">
								<span class="ve-col-4-5 px-2">${ae.path}</span>
								<span class="ve-col-2-5 ve-text-center code">${JSON.stringify(val)}</span>
								<span class="ve-col-2-5 ve-text-center code">${JSON.stringify(_val)}</span>
								<span class="ve-col-2-5 ve-text-center code">${JSON.stringify(ae.default)}</span>
							</label>`
								.click(() => {
									const cleanDefault = ae.default == null
										? ae.default
										: typeof ae.default === "object" ? JSON.stringify(ae.default) : ae.default;

									$iptKey.val(ae.path);
									$selMode.val(`${CONST.ACTIVE_EFFECT_MODES.OVERRIDE}`);
									if (!($iptValue.val() || "").trim()) $iptValue.val(cleanDefault);

									doClose();
								});

							const listItem = new ListItem(
								ix,
								$ele,
								ae.path,
								{
									value: val ? MiscUtil.copyFast(val) : val,
									default: ae.default,
									baseValue: _val ? MiscUtil.copyFast(_val) : _val,
								},
							);
							list.addItem(listItem);
						});
						list.init();
						list.update();

						$$($modalInner)`<div class="ve-flex-col h-100 min-h-0">
							<div class="ve-flex-v-stretch input-group input-group--top">
								${$iptSearch}
								${$btnReset}
							</div>
							${$wrpBtnsSort}
							${$wrpList}
						</div>`;

						doAutoResize();
					})
					.prependTo($row);
			});
	}
}

class ExpressionEvaluator {
		static _IGNORE_AE_KEY_PARSE_FAIL_PREFIXES = [
				"ATL.",
		"[[/r ",
		"[[/roll ",
	];

	static _RE_STATUSES = /^statuses\.[a-zA-Z0-9]+$/i;

		static getEvaluatedExpression (doc, expression, rollData, {activeEffectKey = null} = {}) {
		return this.getEvaluatedExpressionMeta(doc, expression, rollData, {activeEffectKey}).value;
	}

	static getEvaluatedExpressionMeta (doc, expression, rollData, {activeEffectKey = null} = {}) {
		if (!`${expression || ""}`.trim()) {
			return {
				value: 0,
				isEvaluated: true,
			};
		}

		expression = `${expression}`;

		const expressionMerged = expression
			.replace(/@(?<path>[-a-zA-Z0-9.]+)/g, (...m) => {
				const {path} = m.at(-1);
				const out = foundry.utils.getProperty(rollData, path);
				if (out !== undefined) return out;

								if (this._RE_STATUSES.test(path)) return 0;

				console.warn(...LGT, `Failed to resolve attribute "${path}" in expression "${expression}" for ${doc.documentName} "${doc.name}" (${doc.id})`);
				return 0;
			})
						.replace(/\btrue\b/g, "1")
			.replace(/\bfalse\b/g, "0")
			.replace(/\bnull\b/g, "0")
		;
		let wrpTree;
		try {
			wrpTree = Renderer.dice.lang.getTree3(expressionMerged, false);
		} catch (e) {
			if (activeEffectKey && this._IGNORE_AE_KEY_PARSE_FAIL_PREFIXES.some(prefix => activeEffectKey.startsWith(prefix))) return 0;

			console.warn(...LGT, `Failed to parse expression "${expression}" ("${expressionMerged}" with roll data applied) in ${doc.documentName} (${doc.name}) ${doc.id} active effects`, e.message);
			return {value: 0, isEvaluated: false};
		}

		return {
			value: wrpTree.tree.evl({}),
			isEvaluated: true,
		};
	}
}

class Patcher_RollData {
	static init () {
		if (game.user.isGM) return;
		this._init_player_bindCharacterUpdateHook();
	}

		static _init_player_bindCharacterUpdateHook () {
		Hooks.on("updateActor", (actor) => {
			if (!Config.get("actor", "isRefreshOtherOwnedSheets")) return;
			if (game.user.character?.id !== actor?.id) return;

			const toRefresh = game.actors.contents.filter(act => {
				if (game.user.character.id === act.id || !act.isOwner) return false;

				let found = false;
				Patcher_RollData._PLAYER_CONTROLLED_NON_CHARS_WALKER.walk(
					[
						act.system._source,
						act.items._source,
						act.effects._source,
					],
					{
						string: (str) => {
							if (!str.includes(Patcher_RollData._PLAYER_CONTROLLED_NON_CHARS_SENTINEL)) return;
							return found = true;
						},
					},
				);
				return found;
			});

			toRefresh.forEach(act => {
				act.reset();
				if (UtilDocumentSheet.hasSheet(act)) act.sheet.render();
			});
		});
	}

	static addAdditionalRollDataBase (rollData, entity) {
		const userChar = Patcher_RollData._getUserChar(entity);

						const pb = userChar?.system?.attributes?.prof;
		let baseSpellAttackMod = 0;
		if (userChar) {
			const scAbility = userChar ? userChar.system.attributes?.spellcasting || "int" : null;
			baseSpellAttackMod = (userChar.system?.abilities?.[scAbility]?.mod ?? 0)
				+ (pb ?? 0);
		}

		rollData[SharedConsts.MODULE_ID_FAKE] = {
			self: {
								name: entity.name,
			},
			name: {
								[entity.name.toLowerCase().replace(/[^a-zA-Z0-9]/g, "")]: 1,
			},
			user: {
				id: game.user.id,
			},
			userchar: {
				id: userChar?.id,
				pb,
				spellAttackRanged: baseSpellAttackMod,
				spellAttackMelee: baseSpellAttackMod,
				spellSaveDc: 8 + baseSpellAttackMod,
				spellMod: baseSpellAttackMod,

				abilities: userChar?.system?.abilities,
				attributes: userChar?.system?.attributes,
				details: userChar?.system?.details,
				traits: userChar?.system?.traits,
				currency: userChar?.system?.currency,
				skills: userChar?.system?.skills,
				spells: userChar?.system?.spells,
				bonuses: userChar?.system?.bonuses,
				resources: userChar?.system?.resources,
				movement: userChar?.system?.movement,

				classes: userChar?.classes
					? this._getRollData_userChar_classes({userChar})
					: undefined,
			},
		};

				if (userChar && baseSpellAttackMod) {
			rollData[SharedConsts.MODULE_ID_FAKE].userchar.spellAttackRanged += ExpressionEvaluator.getEvaluatedExpression(entity, userChar.system?.bonuses?.rsak?.attack, rollData);
			rollData[SharedConsts.MODULE_ID_FAKE].userchar.spellAttackMelee += ExpressionEvaluator.getEvaluatedExpression(entity, userChar.system?.bonuses?.msak?.attack, rollData);

			rollData[SharedConsts.MODULE_ID_FAKE].userchar.spellSaveDc += ExpressionEvaluator.getEvaluatedExpression(entity, userChar.system?.bonuses?.spell?.dc, rollData);

					}
		
		const idAddItemsFeat = Config.get("actor", "isAddRollDataItemsFeat");
		const idAddItemsItem = Config.get("actor", "isAddRollDataItemsItem");
		const idAddItemsSpell = Config.get("actor", "isAddRollDataItemsSpell");
		const idAddItemsOther = Config.get("actor", "isAddRollDataItemsOther");
		if (
			(
				idAddItemsFeat
				|| idAddItemsItem
				|| idAddItemsSpell
				|| idAddItemsOther
			) && entity.items?.size
		) {
			rollData[SharedConsts.MODULE_ID_FAKE].items = {};

			entity.items
				.filter(itm => {
					if (itm.type === "feat") return idAddItemsFeat;
					if (itm.type === "spell") return idAddItemsSpell;
					if (UtilDocumentItemItem.TYPES_ITEM.has(itm.type)) return idAddItemsItem;
					return idAddItemsOther;
				})
				.forEach(itm => {
					rollData[SharedConsts.MODULE_ID_FAKE].items[UtilDocumentItem.getNameAsIdentifier(itm.name)] = {...itm};
				});
		}
	}

	static _getUserChar (entity) {
		if (!game.user.isGM) return game.user.character;

		if (game.user.isGM && game.user.character && Config.get("actor", "isDebugForceGmUserCharLink")) return game.user.character;

		for (let i = 0; i < 3 && entity?.parent; ++i) {
						if (entity.parent instanceof TokenDocument) break;
			entity = entity.parent;
		}
		if (!entity) return null; 
				if (game.users.contents.some(it => it.character?.id === entity.id)) return entity;

		const potentialUsers = Object.entries(entity.ownership)
			.filter(([userId, permLevel]) => permLevel >= CONST.DOCUMENT_OWNERSHIP_LEVELS.OWNER && !game.users.get(userId)?.isGM)
			.map(([userId]) => userId);

		if (potentialUsers.length !== 1) return null;

		return game.users.get(potentialUsers[0])?.character;
	}

	static _getRollData_userChar_classes ({userChar}) {
		const cpy = {...userChar.classes};

		Object.entries(cpy)
			.forEach(([k, item]) => {
				cpy[k] = item?.system;
			});

		return cpy;
	}

		static addBabeleCompatibilityRollData (rollData, actor) {
		if (!UtilCompat.isBabeleActive()) return;

		actor.items.filter(it => it.type === "class")
			.forEach(item => {
				const originalName = IntegrationBabele.getOriginalName(item);
				if (!originalName || originalName === item.name) return;

								const originalNameSlug = originalName.slugify({strict: true});

								if (rollData?.classes?.[originalNameSlug]) return;

				MiscUtil.set(rollData, "classes", originalNameSlug, item.system);
			});
	}
}
Patcher_RollData._PLAYER_CONTROLLED_NON_CHARS_WALKER = MiscUtil.getWalker({isNoModification: true, isBreakOnReturn: true});
Patcher_RollData._PLAYER_CONTROLLED_NON_CHARS_SENTINEL = `@${SharedConsts.MODULE_ID_FAKE}.userchar.`;

class Patcher_Actor {
	static init () {
		this._init_tryPatchGetRollData();
		this._init_tryPatchApplyActiveEffects();
	}

	static _init_tryPatchGetRollData () {
		try {
			UtilLibWrapper.addPatch(
				"CONFIG.Actor.documentClass.prototype.getRollData",
				this._lw_CONFIG_Actor_documentClass_prototype_getRollData,
				UtilLibWrapper.LIBWRAPPER_MODE_WRAPPER,
			);
		} catch (e) {
			console.error(...LGT, `Failed to bind getRollData handler!`, e);
		}
	}

	static _HAS_RUN_LATE_INIT_PREPARE_ACTOR_DATA = false;
	static lateInit () {
		if (!Config.get("actor", "isUseExtendedActiveEffectsParser")) return;

		if (!UtilCompat.isObsidianActive()) return this._lateInit_resetActorData();
		Hooks.once("obsidian.actorsPrepared", () => this._lateInit_resetActorData());
	}

		static _TOO_MANY_ACTORS_THRESH = 100;
	static _ONE_MONTH_MS = 30 * 24 * 60 * 60 * 1000;

	static _getRefreshAllModifiedTimeThresh () {
		return game.actors?.length <= this._TOO_MANY_ACTORS_THRESH
			? null
			: (Date.now() - this._ONE_MONTH_MS);
	}

	static _isWithinRefreshAllModifiedTimeThresh (ent, thresh) {
		if (thresh == null) return true;
		const tModified = ent?._stats?.modifiedTime;
		if (tModified == null) return true;
		return tModified >= thresh;
	}
	
	static _lateInit_resetActorData () {
		const modifiedTimeThresh = this._getRefreshAllModifiedTimeThresh();

		(game.actors || [])
			.forEach(ent => {
				if (!this._isWithinRefreshAllModifiedTimeThresh(ent, modifiedTimeThresh)) return;

				try {
					ent.reset();
				} catch (e) {
					const msg = `Failed to apply custom active effect parsing to actor "${ent.id}"!`;
					ui.notifications.error(`${msg} ${VeCt.STR_SEE_CONSOLE}`);
					console.error(...LGT, msg);
					console.error(e);
				}
			});

		this._HAS_RUN_LATE_INIT_PREPARE_ACTOR_DATA = true;
	}

	static _lw_CONFIG_Actor_documentClass_prototype_getRollData (fn, ...args) {
		const out = fn(...args);
		return Patcher_Actor._getRollData(this, out);
	}

	static _getRollData (actor, rollData) {
		if (!rollData) return rollData;
		Patcher_RollData.addAdditionalRollDataBase(rollData, actor);
		Patcher_RollData.addBabeleCompatibilityRollData(rollData, actor);
		return rollData;
	}

	static _init_tryPatchApplyActiveEffects () {
		UtilLibWrapper.addPatch(
			"Actor.prototype.applyActiveEffects",
			this._lw_Actor_prototype_applyActiveEffects,
			UtilLibWrapper.LIBWRAPPER_MODE_MIXED,
		);

		UtilHooks.on(UtilHooks.HK_CONFIG_UPDATE, () => this._handleConfigUpdate());
	}

	static _lw_Actor_prototype_applyActiveEffects (fn, ...args) {
		if (!Config.get("actor", "isUseExtendedActiveEffectsParser")) return fn(...args);
		return Patcher_Actor._applyActiveEffects(this, ...args);
	}

	static _handleConfigUpdate () {
		if (!this._HAS_RUN_LATE_INIT_PREPARE_ACTOR_DATA) return;

		const modifiedTimeThresh = this._getRefreshAllModifiedTimeThresh();

		game.actors
			.forEach(act => {
				const hasSheet = UtilDocumentSheet.hasSheet(act);

								if (!hasSheet && !this._isWithinRefreshAllModifiedTimeThresh(act, modifiedTimeThresh)) return;

				act.reset();
				if (hasSheet) act.sheet.render();
			});
	}

		static _applyActiveEffects (actor) {
		const overrides = {};

		actor.statuses ??= new Set();
				const specialStatuses = new Map();
		for (const statusId of Object.values(CONFIG.specialStatusEffects)) {
			specialStatuses.set(statusId, actor.statuses.has(statusId));
		}
		actor.statuses.clear();

				const changes = [];
		for (const effect of actor.allApplicableEffects()) {
			if (!effect.active) continue;
			changes.push(...effect.changes.map(change => {
				const c = foundry.utils.deepClone(change);
				c.effect = effect;
				c.priority = c.priority ?? (c.mode * 10);
				return c;
			}));
			for (const statusId of effect.statuses) actor.statuses.add(statusId);
		}
		changes.sort((a, b) => a.priority - b.priority);

		Patcher_Actor._applyActiveEffects_mutValues(actor, changes);

				for (let change of changes) {
			if (!change.key) continue;
			const changes = change.effect.apply(actor, change);
			Object.assign(overrides, changes);
		}

				actor.overrides = foundry.utils.expandObject(overrides);

				let tokens;
		for (const [statusId, wasActive] of specialStatuses) {
			const isActive = actor.statuses.has(statusId);
			if (isActive === wasActive) continue;
			tokens ??= actor.getActiveTokens();
			for (const token of tokens) token._onApplyStatusEffect(statusId, isActive);
		}
	}

	static _applyActiveEffects_getType ({actor, change, activeEffectsLookup}) {
		const type = UtilActiveEffects.getActiveEffectType(activeEffectsLookup, change.key);
		if (type !== undefined) return type;
		const current = foundry.utils.getProperty(actor, change.key) ?? null;
		return foundry.utils.getType(current);
	}

	static _CACHE_ACTIVE_EFFECTS_LOOKUP = null;

	static _applyActiveEffects_mutValues (actor, changes) {
		if (!changes.length) return;

								let rollData; 
				Patcher_Actor._CACHE_ACTIVE_EFFECTS_LOOKUP ||= UtilActiveEffects.getAvailableEffectsLookup(actor, {isActorEffect: true});

		changes
			.forEach(change => {
								if (typeof change.value !== "string") return;

																				const type = Patcher_Actor._applyActiveEffects_getType({actor, change, activeEffectsLookup: Patcher_Actor._CACHE_ACTIVE_EFFECTS_LOOKUP});

				switch (type) {
										case "object":
					case "array": {
						try {
														change.value = eval(change.value);
						} catch (e) {
														if (Util.isDebug()) console.error(...LGT, e);
						}
						break;
					}

																														case undefined:
					case "undefined":
					case null:
					case "null": {
						if (!rollData) rollData = Patcher_Actor._applyActiveEffects_getFullRollData(actor);

						try {
							const {value, isEvaluated} = ExpressionEvaluator.getEvaluatedExpressionMeta(actor, change.value, rollData, {activeEffectKey: change.key});

														if (!isEvaluated) break;

														change.value = value == null ? "" : `${value}`;
						} catch (e) {
														if (Util.isDebug()) console.error(...LGT, e);
						}

						break;
					}
					case "number": 					case "boolean": { 						if (!rollData) rollData = Patcher_Actor._applyActiveEffects_getFullRollData(actor);

						try {
							change.value = ExpressionEvaluator.getEvaluatedExpression(actor, change.value, rollData, {activeEffectKey: change.key});

														if (type === "boolean") change.value = !!change.value;
						} catch (e) {
														if (Util.isDebug()) console.error(...LGT, e);
						}

						break;
					}

					case "string": 					default: break;
				}
			});
			}

		static _applyActiveEffects_getFullRollData (actor) {
		const cpyActorData = MiscUtil.copyFast(actor.toObject());

		this._applyActiveEffects_recurseDeleteEffects("Actor", cpyActorData);

				const cpyActor = new CONFIG.Actor.documentClass({...cpyActorData});
		cpyActor.reset();
		return cpyActor.getRollData();
	}

	static _applyActiveEffects_recurseDeleteEffects (clazzName, json) {
				const ClsEmbedDocSub = eval(clazzName);

		Object.entries(ClsEmbedDocSub.metadata?.embedded || {})
			.forEach(([clazzName, propCollection]) => {
				if (clazzName === "ActiveEffect") return json[propCollection] = [];

				(json[propCollection] || [])
					.forEach(jsonSub => this._applyActiveEffects_recurseDeleteEffects(clazzName, jsonSub));
			});
	}

		static handleHookApplyActiveEffect (actor, change) {
		if (!Config.get("actor", "isUseExtendedActiveEffectsParser")) return;
		if (!(change.key || "").startsWith(SharedConsts.MODULE_ID_FAKE)) return;

		const key = UtilActiveEffects.getKeyFromCustomKey(change.key);

		switch (key) {
									case "system.attributes.ac.flat": {
								const {value} = change;
				const current = foundry.utils.getProperty(actor.system, key);
				if ((typeof (current) === "number") && (current >= Number(value))) return null;
				setProperty(actor.system, key, value);
				return;
							}
			
			default: console.warn(...LGT, `Unhandled custom active effect key: ${key}`);
		}
	}
}

