class NamedTokenCreator {
	static async pCreateToken (
		{
			name,
			xScene,
			yScene,
			width = 1,
			height = 1,
			scale = 1,

			styleHint = null,
			backgroundUrl = null,
			font = `"Modesto Condensed", "Palatino Linotype", serif`,
			textColor = null,
			textShadowColor = null,
		},
	) {
		if (!canvas.scene) throw new Error(`There is currently no active scene!`);

		styleHint ||= Config.getRulesVersion();
		backgroundUrl = this._getBackgroundUrl({styleHint, backgroundUrl});

		textColor = styleHint === SITE_STYLE__CLASSIC ? "#d0c04c" : "#111111";
		textShadowColor = styleHint === SITE_STYLE__CLASSIC ? "#000000" : "#dddddd";
		const textInsetXY = styleHint === SITE_STYLE__CLASSIC ? 0 : 27;

		const img = await UtilImage.pLoadTempImage(backgroundUrl, {isCacheable: true});
		const tokenBlob = await this._pGetTokenBlob(
			{
				name,
				img,
				font,
				textColor,
				textShadowColor,
				textInsetXY,
			},
		);
		const url = await VetoolsSaverImages.pSaveImageToServerAndGetUrl({blob: tokenBlob, path: `named-token/${name}.webp`});
		return this._pCreateToken({name, url, xScene, yScene, width, height, scale});
	}

	static _getBackgroundUrl ({styleHint, backgroundUrl = null}) {
		if (backgroundUrl) return backgroundUrl;
		if (styleHint === SITE_STYLE__CLASSIC) return `modules/${SharedConsts.MODULE_ID}/media/img/blank.png`;
		return `modules/${SharedConsts.MODULE_ID}/media/img/blank-2024.webp`;
	}

	static _pGetTokenBlob (
		{
			name,
			img,
			font,
			textColor,
			textShadowColor,
			textInsetXY,
		},
	) {
		return UtilImage.pDrawTextGetBlob({
			text: name,
			img,
			color: textColor,
			shadowColor: textShadowColor,
			font,
			textInsetX: textInsetXY,
			textInsetY: textInsetXY,
		});
	}

	static _pCreateToken ({name, url, xScene, yScene, width, height, scale}) {
				return TokenDocument.implementation.create(
			{
				name,
				x: xScene,
				y: yScene,
				texture: {
					src: url,
					scaleX: scale,
					scaleY: scale,
				},
				width: width,
				height: height,
			},
			{
				parent: canvas.scene,
			},
		);
	}
}

class ConfigUtils {
		static api_getWikiSummary () {
		return this.getWikiSummary();
	}

	static api_getWikiSummaryMarkdown () {
		return this.getWikiSummaryMarkdown();
	}
	
	static getWikiSummary () {
		const getAsConfigSettings = (settings, section) => {
			return Object.values(settings || {})
				.filter(({unlockCode}) => !unlockCode)
				.map(setting => {
					const configSetting = ConfigSettingInfoFactory.getSettingInfo(setting);
					return configSetting.getWikiSummary({section});
				});
		};

		return ConfigConsts.getDefaultConfigSorted_().map(([, group]) => {
			return {
				groupName: group.name,
				settings: [
					...getAsConfigSettings(group.settings, "standard"),
					...getAsConfigSettings(group.settingsAdvanced, "advanced"),
					...getAsConfigSettings(group.settingsHacks, "hacks"),
				],
			};
		});
	}

	static getWikiSummaryMarkdown () {
		return this.getWikiSummary()
			.map(group => {
				let markdown = `## ${group.groupName}\n`;
				markdown += "TODO: Add description\n";

				const settingsTypes = {};
				group.settings.forEach(setting => {
					const typeName = setting.type.toTitleCase();
					settingsTypes[typeName] = [...(settingsTypes[typeName] || []), setting];
				});

				Object.entries(settingsTypes)
					.forEach(([typeName, settings]) => {
						markdown += `### ${typeName}\n`;
						settings.forEach(setting => {
							markdown += `- **${setting.name}**${(!setting.default && setting.default !== false) ? "" : ` *(default: ${setting.default})*`} - ${setting.description}\n`;

							if (setting.options) {
								if (setting.options.length > 10 && setting.options[0].value === ConfigConsts.C_USE_GAME_DEFAULT) {
									markdown += `	- *${setting.options[0].name}*\n`;
									markdown += "	- *Use one of many custom values*\n";
								} else {
									markdown += "	Possible options are:\n";
									setting.options.forEach(option => markdown += `	- *${option.name}*${option.help ? `: ${option.help}` : ""}\n`);
								}
							}
						});
					});

				return markdown.replaceAll(/((&quot;)|")/g, "`");
			})
			.join("");
	}
}

